.project-exact-deadline { color: var(--text-secondary); font-size: .85rem; margin: 0 0 .65rem; overflow-wrap: anywhere; }
.project-exact-deadline strong { color: var(--text-primary); font-weight: 600; }
.subscription-free-label { display: block; color: var(--status-green); font-size: .8rem; margin-top: .35rem; }
.tracker-pause-button { width: 100%; margin: .5rem 0; }
.vehicle-pause-button { width: auto; max-width: 100%; margin: 0; padding: .35rem .6rem; font-size: .75rem; flex-shrink: 0; }
.vehicle-paused-note { color: var(--text-secondary); font-size: .8rem; padding: .4rem; }
.is-tracker-paused { border-color: var(--text-secondary) !important; }
.custom-tracker-card.status-paused .custom-tracker-progress span { background: var(--text-secondary); }
/* Palette, typography and shared tokens live in design-tokens.css. */

/* Finance workspace: explicit money/currency boundaries, same visual language. */
#finance-workspace { min-width: 0; }
.fw-toolbar, .fw-heading, .fw-controls, .fw-actions, .fw-footer, .fw-pagination, .fw-transfer { display: flex; align-items: center; gap: .75rem; flex-wrap: wrap; }
.fw-toolbar, .fw-heading, .fw-transfer { justify-content: space-between; }
.fw-toolbar { margin-bottom: 1.5rem; }
.fw-toolbar h2 { margin: .35rem 0; }
.fw-eyebrow { color: var(--text-secondary); font-size: .7rem; font-weight: 700; letter-spacing: .12em; }
.fw-controls { margin-bottom: 1rem; align-items: flex-end; }
.fw-controls label, .fw-form-grid label { display: grid; gap: .4rem; color: var(--text-secondary); font-size: .85rem; min-width: 0; }
.fw-controls input, .fw-controls select, .fw-dialog input, .fw-dialog select { background: var(--control-bg); color: var(--text-primary); border: 1px solid var(--surface-border); border-radius: .65rem; padding: .7rem; min-width: 0; width: 100%; font: inherit; color-scheme: var(--native-color-scheme); }
#finance-workspace button, .fw-dialog button { cursor: pointer; font: inherit; border-radius: .7rem; padding: .65rem .9rem; border: 1px solid var(--surface-border); color: var(--text-primary); background: var(--surface-color); width: auto; margin: 0; }
#finance-workspace .btn-primary, .fw-dialog .btn-primary { background: var(--primary-color); color: var(--text-on-accent); }
.fw-tabs { display: flex; flex-wrap: wrap; gap: .4rem; padding: .4rem; background: var(--surface-section); border: 1px solid var(--surface-border); border-radius: 1rem; }
#finance-workspace .fw-tabs [aria-current=page] { background: var(--primary-color); color: var(--text-on-accent); }
.fw-note { color: var(--text-secondary); font-size: .8rem; line-height: 1.55; margin: 1rem 0; }
.fw-metrics { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 1rem; margin: 1.5rem 0; }
.fw-metric, .fw-panel { background: var(--surface-color); border: 1px solid var(--surface-border); border-radius: 1rem; padding: 1.3rem; min-width: 0; }
.fw-metric span { display: block; font-size: .85rem; color: var(--text-secondary); }
.fw-metric small { display:block; margin-top:.65rem; color:var(--text-secondary); line-height:1.5; overflow-wrap:anywhere; }
.fw-warning { color:var(--status-yellow); font-size:.85rem; line-height:1.5; }
.fw-current-balance { margin:1.25rem 0; }
.fw-movement-end small { display:block; margin:.35rem 0; }
.fw-metric strong, .fw-balance { display: block; margin-top: .5rem; font-size: clamp(1.3rem,2.5vw,2rem); overflow-wrap: anywhere; }
.fw-income { border-color: var(--status-green); }.fw-expense { border-color: var(--status-red); }
.fw-positive, .fw-income strong { color: var(--status-green); }.fw-negative, .fw-expense strong { color: var(--status-red); }
.fw-columns, .fw-account-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 1rem; margin-bottom: 1.5rem; }
.fw-panel h3 { margin: 0 0 .7rem; overflow-wrap: anywhere; }
.fw-panel p { color: var(--text-secondary); line-height: 1.55; }
.fw-panel .fw-negative { color: var(--status-red); }.fw-panel .fw-positive { color: var(--status-green); }
.fw-panel progress { width: 100%; accent-color: var(--primary-color); height: .5rem; }
.fw-category { margin: .75rem 0; }.fw-category > div { display: flex; justify-content: space-between; gap: 1rem; margin-bottom: .3rem; }
.fw-movements { display: grid; gap: .65rem; margin: 1rem 0; }
.fw-movement { display: flex; justify-content: space-between; gap: 1rem; align-items: center; border: 1px solid var(--surface-border); background: var(--surface-section); border-radius: .9rem; padding: 1rem; }
.fw-movement > div { min-width: 0; }.fw-movement h4 { margin: .35rem 0; overflow-wrap: anywhere; }
.fw-movement p, .fw-movement small { color: var(--text-secondary); font-size: .75rem; line-height: 1.5; margin: .25rem 0; overflow-wrap: anywhere; }
.fw-kind { font-size: .75rem; }.fw-movement-end { display: grid; justify-items: end; gap: .6rem; flex-shrink: 1; max-width:100%; }.fw-movement-end > div { display:flex; gap: .3rem; flex-wrap:wrap; justify-content:flex-end; max-width:100%; }
#finance-workspace .fw-movement button { padding: .35rem .6rem; font-size: .75rem; }
.fw-heading { margin: 1.2rem 0; }.fw-heading > div { display: flex; flex-wrap: wrap; gap: .5rem; }
.fw-empty { padding: 3rem 1.5rem; text-align: center; border: 1px dashed var(--surface-border); border-radius: 1rem; color: var(--text-secondary); }
.fw-footer { margin: 1.5rem 0; }.fw-transfer { padding: .8rem 0; border-bottom: 1px solid var(--surface-border); font-size: .85rem; }.fw-transfer span { overflow-wrap: anywhere; }
.fw-legacy { margin-top: 2rem; }.fw-legacy > summary { cursor: pointer; color: var(--text-secondary); padding: 1rem 0; }
.fw-dialog { color: var(--text-primary); background: var(--surface-solid); border: 1px solid var(--surface-border); border-radius: 1.25rem; width: min(640px,calc(100vw - 24px)); max-height: calc(100dvh - 32px); padding: 1.5rem; margin: auto; overflow-wrap: anywhere; }
.fw-dialog::backdrop { background: var(--overlay-bg); backdrop-filter: blur(4px); }.fw-dialog .fw-heading { margin-top: 0; }.fw-dialog h2 { font-size: 1.3rem; }
.fw-form-grid { display: grid; grid-template-columns: minmax(0,1fr); gap: 1rem; }.fw-form-grid > * { min-width: 0; }.fw-form-grid small { display: block; color: var(--text-secondary); margin-top: .4rem; }.fw-dialog .fw-actions { justify-content: flex-end; }
.fw-original-list { display:grid; gap:.5rem; max-height:45dvh; overflow:auto; padding:.25rem; }
.fw-form-grid .fw-original-choice { display:flex; flex-direction:row; align-items:flex-start; gap:.75rem; padding:.75rem; border-bottom:1px solid var(--surface-border); overflow-wrap:anywhere; }
.fw-dialog .fw-original-choice input { width:1.2rem; height:1.2rem; flex-shrink:0; margin:.15rem 0 0; accent-color:var(--primary-color); }
.fw-original-choice span { min-width:0; }
#fw-income-chart { margin:1.25rem 0; }
.fw-income-svg { width:100%; max-height:280px; display:block; overflow:visible; }
.fw-income-svg text { fill:var(--text-secondary); font:11px system-ui,sans-serif; }
.fw-chart-grid { stroke:var(--surface-border); stroke-dasharray:3 4; }
.fw-chart-line { fill:none; stroke:var(--status-green); stroke-width:2.5; stroke-linejoin:round; }
.fw-chart-point { fill:var(--status-green); stroke:var(--surface-solid); stroke-width:2; }
.fw-chart-estimated { fill:var(--surface-solid); stroke:var(--status-yellow); stroke-width:2; }
.fw-income-svg [role=button] { cursor:pointer; }
.fw-income-svg [aria-pressed=true] circle { stroke-width:3; }
.fw-income-svg [aria-pressed=true] .fw-chart-point { stroke:var(--text-primary); }
.fw-income-svg [role=button]:focus-visible { outline:2px solid var(--primary-color); }
#fw-income-chart label { display:grid; gap:.4rem; color:var(--text-secondary); font-size:.85rem; }
#fw-income-chart select { background:var(--control-bg); color:var(--text-primary); border:1px solid var(--surface-border); border-radius:.65rem; padding:.7rem; width:100%; min-width:0; font:inherit; }
.fw-chart-table { overflow-x:auto; }.fw-chart-table table { width:100%; border-collapse:collapse; font-size:.85rem; }
.fw-chart-table th,.fw-chart-table td { padding:.65rem; text-align:left; border-bottom:1px solid var(--surface-border); }
#fw-form-error { color: var(--status-red); min-height: 1.2rem; } #finance-workspace [hidden], .fw-dialog [hidden] { display: none !important; }
#finance-workspace :focus-visible, .fw-dialog :focus-visible { outline: 3px solid var(--primary-color); outline-offset: 3px; }
@media (max-width: 680px) {
    .fw-metrics, .fw-columns, .fw-account-grid { grid-template-columns: 1fr; }
    .fw-metric { padding: 1rem; }.fw-controls > label { flex: 1 1 180px; }
    .fw-movement { flex-direction: column; align-items: stretch; }.fw-movement-end { justify-items: start; }
    .fw-tabs button { flex: 1 1 auto; font-size: .85rem !important; }.fw-toolbar .btn-primary { width: 100% !important; }
    .fw-dialog { padding: 1rem; }
}

/* Suscripciones */
.subscription-card {
    display: flex;
    flex-direction: column;
    gap: .85rem;
    min-width: 0;
    padding: 1.15rem;
}

.subscription-card-heading,
.subscription-price,
.subscription-actions {
    display: flex;
    align-items: center;
    gap: .65rem;
}

.subscription-card-heading {
    justify-content: space-between;
    align-items: flex-start;
}

.subscription-card-heading h3 {
    margin: .15rem 0 0;
    overflow-wrap: anywhere;
}

.subscription-category {
    color: var(--text-secondary);
    font-size: .72rem;
    font-weight: 700;
    letter-spacing: .05em;
    text-transform: uppercase;
}

.subscription-price {
    align-items: baseline;
    flex-wrap: wrap;
}

.subscription-price strong {
    color: var(--text-primary);
    font-size: 1.35rem;
}

.subscription-price span,
.subscription-price small {
    color: var(--text-secondary);
}

.subscription-price small {
    margin-left: auto;
}

.subscription-meta {
    display: grid;
    gap: .55rem;
    margin: 0;
    padding: .75rem 0;
    border-block: 1px solid var(--surface-border);
}

.subscription-meta div {
    display: flex;
    justify-content: space-between;
    gap: 1rem;
}

.subscription-meta dt { color: var(--text-secondary); }
.subscription-meta dd { margin: 0; color: var(--text-primary); text-align: right; }
.subscription-history summary { cursor: pointer; color: var(--text-secondary); }
.subscription-history ul { margin: .65rem 0 0; padding-left: 1.15rem; color: var(--text-secondary); }
.subscription-actions { flex-wrap: wrap; justify-content: flex-end; }
.subscription-actions .btn { width: auto; margin: 0; padding: .45rem .7rem; font-size: .78rem; }
.subscription-alert-settings { display: grid; grid-template-columns: minmax(90px, .7fr) minmax(180px, 1.3fr); gap: .75rem; }
.subscription-extra-alert-time { display: flex; align-items: center; gap: .4rem; margin-top: .4rem; }
#btn-add-subscription-alert-time { width: auto; margin-top: .45rem; padding: .4rem .65rem; font-size: .8rem; }

#suscripciones-section .section-header > .btn,
#transcripciones-section .section-header > div:last-child .btn,
#btn-new-transcription-folder {
    width: auto;
    margin: 0;
}

.subscription-card-heading > div,
.transcription-card-heading > div {
    min-width: 0;
}

.subscription-card-heading .badge,
.transcription-card-heading .badge {
    flex: 0 0 auto;
    white-space: nowrap;
}

/* Transcripciones */
.card.transcription-availability {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: .7rem;
    margin-bottom: 1rem;
    padding: .9rem 1rem;
    color: var(--text-secondary);
}

.subscription-modal-content .modal-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 1.25rem;
}

.subscription-modal-content .modal-header h3 {
    margin: 0;
}

#subscription-form {
    display: grid;
    gap: 1rem;
}

#subscription-form .input-group {
    min-width: 0;
    margin: 0;
    text-align: left;
}

#subscription-form .input-group > small {
    color: var(--text-secondary);
    font-size: .78rem;
    line-height: 1.4;
}

.subscription-form-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: .75rem;
}

.subscription-form-row--money {
    grid-template-columns: minmax(0, 1fr) 120px;
}

.subscription-toggle {
    display: flex;
    align-items: flex-start;
    gap: .65rem;
    color: var(--text-primary);
    line-height: 1.4;
    cursor: pointer;
}

.subscription-toggle > input {
    flex: 0 0 auto;
    width: 18px;
    height: 18px;
    margin-top: .05rem;
    accent-color: var(--primary-color);
}

.subscription-alert-card {
    min-width: 0;
    margin: 0;
    padding: 1rem;
    border: 1px solid var(--surface-border);
    border-radius: var(--border-radius-sm);
    background: var(--surface-subtle);
}

.subscription-alert-card > legend {
    padding: 0 .4rem;
    color: var(--text-secondary);
    font-size: .82rem;
    font-weight: 700;
}

.subscription-alert-enabled {
    margin-bottom: 1rem;
}

.subscription-modal-actions {
    justify-content: flex-end;
    margin-top: .25rem;
}

.subscription-modal-actions .btn {
    width: auto;
    margin: 0;
}

.transcription-availability > i {
    flex: 0 0 auto;
    color: var(--status-green);
    font-size: 1.2rem;
}

.transcription-availability.is-error {
    border-color: color-mix(in srgb, var(--status-red) 36%, var(--surface-border));
}

.transcription-availability.is-error > i {
    color: var(--status-red);
}

.transcription-capture-settings {
    display: grid;
    grid-template-columns: minmax(220px, 1.2fr) minmax(180px, .8fr) minmax(260px, 1fr);
    align-items: stretch;
    gap: 1rem;
    margin-bottom: 1rem;
    padding: 1rem;
}

.transcription-capture-settings .input-group {
    margin: 0;
}

.subscription-check {
    display: flex;
    align-items: center;
    gap: .7rem;
    min-width: 0;
    padding: .7rem .8rem;
    border: 1px solid var(--surface-border);
    border-radius: var(--border-radius-sm);
    background: var(--surface-subtle);
    color: var(--text-primary);
    cursor: pointer;
}

.subscription-check > input {
    flex: 0 0 auto;
    width: 18px;
    height: 18px;
    accent-color: var(--primary-color);
}

.subscription-check > span {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: .15rem;
}

.subscription-check small {
    color: var(--text-secondary);
    line-height: 1.35;
}

#transcriptions-folder-tabs {
    margin-bottom: 0;
}

.transcription-card {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: .85rem;
    padding: 1.15rem;
}

.transcription-card-heading {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: .75rem;
}

.transcription-card-heading small {
    color: var(--text-secondary);
    font-size: .72rem;
    font-weight: 700;
    letter-spacing: .05em;
    text-transform: uppercase;
}

.transcription-card-heading h3 {
    margin: .15rem 0 0;
    overflow-wrap: anywhere;
}

.transcription-card > p {
    min-height: 3.9em;
    margin: 0;
    color: var(--text-secondary);
    line-height: 1.45;
    overflow-wrap: anywhere;
}

.transcription-card-meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: .75rem;
    padding-top: .75rem;
    border-top: 1px solid var(--surface-border);
    color: var(--text-secondary);
    font-size: .8rem;
}

.transcription-card-actions,
.transcription-artifact-actions {
    display: flex;
    align-items: center;
    gap: .5rem;
    flex-wrap: wrap;
}

.transcription-card-actions {
    margin-top: auto;
}

.transcription-card-actions .btn,
.transcription-artifact-actions .btn,
#transcription-detail-modal .modal-actions .btn {
    width: auto;
    margin: 0;
}

.transcription-card-actions .btn {
    padding: .5rem .75rem;
    font-size: .8rem;
}

.transcription-card-actions .icon-btn {
    margin-left: auto;
}

.transcription-empty {
    grid-column: 1 / -1;
    align-items: center;
    gap: .65rem;
    min-height: 180px;
    justify-content: center;
    color: var(--text-secondary);
    text-align: center;
}

.transcription-detail-status,
.transcription-derived-result,
#transcription-recovery-panel {
    margin-bottom: 1rem;
    padding: .85rem 1rem;
    border: 1px solid var(--surface-border);
    border-radius: var(--border-radius-sm);
    background: var(--surface-subtle);
    color: var(--text-secondary);
    line-height: 1.5;
}

.transcription-derived-result {
    margin-top: 1rem;
    color: var(--text-primary);
}

.transcription-derived-result > div {
    margin-top: .55rem;
    color: var(--text-secondary);
    white-space: pre-wrap;
}

#transcription-detail-modal {
    padding: max(.75rem, env(safe-area-inset-top)) max(.75rem, env(safe-area-inset-right))
        max(.75rem, env(safe-area-inset-bottom)) max(.75rem, env(safe-area-inset-left));
}

#transcription-detail-modal .transcription-detail-content {
    display: flex;
    flex-direction: column;
    width: min(100%, 760px);
    max-width: 760px;
    max-height: calc(100dvh - 1.5rem - env(safe-area-inset-top) - env(safe-area-inset-bottom));
    overflow: hidden;
    padding: 0;
    text-align: left;
}

#transcription-detail-modal .modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: .75rem;
    padding: 1rem 1.25rem;
    margin: 0;
    flex-shrink: 0;
}

#transcription-detail-modal .modal-header h3 { margin: 0; }
#transcription-detail-modal .modal-header .icon-btn { flex-shrink: 0; }
.transcription-detail-body { overflow-y: auto; min-height: 0; padding: 0 1.25rem 1rem; overscroll-behavior: contain; }
.transcription-text-heading { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .5rem; margin-bottom: .5rem; }
#trans-detail-text { min-height: 180px; max-height: 45dvh; resize: vertical; }
#transcription-detail-modal .transcription-detail-actions {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    flex-shrink: 0;
    gap: .75rem;
    margin: 0;
    padding: .85rem 1.25rem;
    border-top: 1px solid var(--surface-border);
}
.transcription-detail-exports, .transcription-detail-save { display: flex; flex-wrap: wrap; gap: .5rem; }

@media (max-width: 560px) {
    #transcription-detail-modal .modal-header { padding: .85rem 1rem; }
    #transcription-detail-modal .modal-header h3 { font-size: 1.15rem; }
    .transcription-detail-body { padding-inline: 1rem; }
    #transcription-detail-modal .transcription-detail-actions { padding: .75rem 1rem; }
    .transcription-detail-save { width: 100%; }
    #transcription-detail-modal .transcription-detail-save .btn { flex: 1; }
    .transcription-artifact-actions .btn { padding: .5rem .65rem; font-size: .85rem; }
}

@media (max-width: 560px) {
    .subscription-form-row,
    .subscription-form-row--money {
        grid-template-columns: 1fr;
    }
    .subscription-modal-actions {
        position: sticky;
        bottom: -1rem;
        z-index: 1;
        margin-inline: -1rem;
        margin-bottom: -1rem;
        padding: .85rem 1rem 1rem;
        border-top: 1px solid var(--surface-border);
        background: var(--surface-solid);
    }
    .subscription-modal-actions .btn {
        flex: 1 1 0;
    }
    .subscription-alert-settings { grid-template-columns: 1fr; }
    .subscription-price small { width: 100%; margin-left: 0; }
    .subscription-meta div { flex-direction: column; gap: .1rem; }
    .subscription-meta dd { text-align: left; }
    .subscription-actions { justify-content: stretch; }
    .subscription-actions .btn { flex: 1 1 45%; }
    #suscripciones-section .section-header > .btn,
    #transcripciones-section .section-header > div:last-child,
    #transcripciones-section .section-header > div:last-child .btn {
        width: 100%;
    }
    .transcription-card-heading,
    .transcription-card-meta {
        align-items: flex-start;
        flex-direction: column;
    }
    .transcription-card > p { min-height: 0; }
    .transcription-card-actions .btn { flex: 1 1 42%; }
    .transcription-card-actions .icon-btn { margin-left: 0; }
    .transcription-artifact-actions { margin-top: .55rem; }
    .transcription-artifact-actions .btn { flex: 1 1 30%; }
}

@media (max-width: 900px) {
    .transcription-capture-settings {
        grid-template-columns: 1fr;
    }
}



* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-family);
    background-color: var(--bg-color);
    color: var(--text-primary);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    overflow-x: hidden;
    transition: background-color 0.22s ease, color 0.22s ease;
}

body.access-locked {
    overflow: hidden;
}

.access-gate {
    position: fixed;
    inset: 0;
    z-index: 10000;
    display: grid;
    place-items: center;
    padding: 1.25rem;
    background:
        radial-gradient(circle at 15% 15%, color-mix(in srgb, var(--primary-color) 20%, transparent), transparent 38%),
        radial-gradient(circle at 85% 80%, rgba(16, 185, 129, 0.12), transparent 34%),
        var(--bg-color);
}

.access-gate-card {
    width: min(100%, 430px);
    max-height: calc(100dvh - 2.5rem);
    overflow-y: auto;
    padding: clamp(1.5rem, 5vw, 2.25rem);
    border: 1px solid var(--surface-border);
    border-radius: 24px;
    background: color-mix(in srgb, var(--surface-solid) 88%, transparent);
    box-shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    backdrop-filter: blur(22px);
}

.access-gate-brand {
    display: flex;
    align-items: center;
    gap: 0.9rem;
    margin-bottom: 1.75rem;
}

.access-gate-icon {
    width: 52px;
    height: 52px;
    display: grid;
    place-items: center;
    flex: 0 0 auto;
    border-radius: 15px;
    color: #fff;
    font-size: 1.7rem;
    background: linear-gradient(135deg, var(--primary-color), var(--primary-hover));
    box-shadow: 0 10px 30px color-mix(in srgb, var(--primary-color) 28.000000000000004%, transparent);
}

.access-gate-brand h1 {
    margin: 0;
    font-size: 1.65rem;
    line-height: 1.15;
}

.access-gate-brand p,
.access-gate-state p {
    margin: 0.25rem 0 0;
    color: var(--text-secondary);
}

.access-gate-state {
    min-height: 150px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    text-align: center;
}

.access-gate-spinner,
.access-gate-warning {
    font-size: 2rem;
    color: var(--primary-color);
}

.access-gate-spinner {
    animation: spin 1s linear infinite;
}

.access-gate-warning {
    color: var(--status-orange);
}

.access-gate-form {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.access-gate-form .input-group {
    margin: 0;
}

.access-gate-form .text-input {
    width: 100%;
}

.access-gate-submit {
    width: 100%;
    margin-top: 0.25rem;
}

.access-gate-register {
    width: 100%;
}

.access-gate-form-heading h2 {
    margin: 0;
    font-size: 1.25rem;
}

.access-gate-form-heading p {
    margin: 0.35rem 0 0;
    color: var(--text-secondary);
    font-size: 0.85rem;
    line-height: 1.45;
}

.access-gate-form .input-group small {
    display: block;
    margin-top: 0.4rem;
    color: var(--text-secondary);
    font-size: 0.75rem;
}

.access-gate-registration-actions {
    display: grid;
    grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
    gap: 0.75rem;
}

.access-gate-registration-actions .btn {
    width: 100%;
}

.access-gate-error {
    margin: 0;
    padding: 0.7rem 0.8rem;
    border: 1px solid rgba(239, 68, 68, 0.3);
    border-radius: 10px;
    color: var(--status-red);
    background: rgba(239, 68, 68, 0.1);
    font-size: 0.85rem;
}

.access-gate-help {
    margin: 0;
    color: var(--text-secondary);
    font-size: 0.78rem;
    line-height: 1.5;
    text-align: center;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

/* Background Effects */
.background-effects {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: -1;
    overflow: hidden;
    pointer-events: none;
}

.glow-orb {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.4;
    animation: float 10s infinite ease-in-out alternate;
}

.orb-1 {
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, color-mix(in srgb, var(--primary-color) 80%, transparent) 0%, color-mix(in srgb, var(--bg-color) 0%, transparent) 70%);
    top: -100px;
    left: -100px;
}

.orb-2 {
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(16,185,129,0.5) 0%, color-mix(in srgb, var(--bg-color) 0%, transparent) 70%);
    bottom: 10%;
    right: -50px;
    animation-delay: -5s;
}

@keyframes float {
    0% { transform: translate(0, 0) scale(1); }
    100% { transform: translate(30px, 50px) scale(1.1); }
}

/* Typography & Layout */
.container {
    width: 100%;
    max-width: 1200px;
    padding: 2rem;
    margin: 0 auto;
}

.app-header {
    display: flex;
    min-height: 48px;
    align-items: center;
    margin: 1.35rem 0 2rem;
    text-align: left;
}

.header-title {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 0.75rem;
    min-width: 0;
}

.app-header-brand {
    display: grid;
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    place-items: center;
    border: 1px solid rgba(96, 165, 250, 0.28);
    border-radius: 12px;
    background: color-mix(in srgb, var(--primary-color) 10%, transparent);
    color: var(--text-link);
    box-shadow: 0 10px 24px rgba(2, 6, 23, 0.2);
}

.app-header-brand i {
    font-size: 1.35rem;
}

.app-header-copy {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 0.08rem;
}

.app-header-product {
    color: var(--text-link);
    font-size: 0.64rem;
    font-weight: 800;
    letter-spacing: 0.12em;
    line-height: 1;
    text-transform: uppercase;
}

.header-title h1 {
    margin: 0;
    overflow: hidden;
    font-size: 1.55rem;
    font-weight: 700;
    letter-spacing: -0.025em;
    background: linear-gradient(135deg, #fff, var(--text-secondary));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.subtitle {
    color: var(--text-secondary);
    font-size: 1.1rem;
    max-width: 600px;
    margin: 0 auto;
}

/* Cards Grid */
.cards-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 2rem;
    align-items: start;
}

/* Card Styles */
.card {
    background: var(--surface-color);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--surface-border);
    border-radius: var(--border-radius-lg);
    padding: 1.5rem;
    box-shadow: var(--shadow-glass);
    transition: var(--transition);
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

.card:hover {
    transform: translateY(-5px);
    border-color: color-mix(in srgb, var(--primary-color) 28%, var(--surface-border));
    box-shadow: 0 15px 35px color-mix(in srgb, var(--text-primary) 14%, transparent);
}

/* Card Header */
.card-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 1.5rem;
}

.card-header:has(h3) {
    justify-content: flex-start;
    gap: 1rem;
    align-items: center;
}

.icon-container {
    width: 50px;
    height: 50px;
    border-radius: var(--border-radius-md);
    background: var(--surface-subtle);
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--surface-border);
}

.icon-container i {
    font-size: 1.8rem;
    color: var(--text-primary);
}

/* Status Indicator */
.status-indicator {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    background: var(--surface-muted);
    padding: 0.4rem 0.8rem;
    border-radius: 2rem;
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.status-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    box-shadow: 0 0 10px currentColor;
}

/* Card Body */
.card-body {
    flex-grow: 1;
}

.card-title {
    font-size: 1.3rem;
    font-weight: 600;
    margin-bottom: 1rem;
}

.time-display {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.days-count {
    font-size: 3.5rem;
    font-weight: 700;
    line-height: 1;
}

.card:not(.hero-card) .days-count {
    margin: 0.5rem 0 1.25rem 0;
}

.days-label {
    font-size: 1.1rem;
    color: var(--text-secondary);
    font-weight: 500;
}

.date-info-container {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
}

.date-info {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.date-info i {
    font-size: 1.1rem;
}

.date-info strong {
    color: var(--text-primary);
    font-weight: 500;
}

/* Progress Bar */
.progress-container {
    height: 6px;
    background: var(--divider-color);
    border-radius: 3px;
    overflow: hidden;
    margin-bottom: 1.5rem;
}

.progress-bar {
    height: 100%;
    border-radius: 3px;
    transition: width 0.5s ease-in-out, background-color 0.5s ease;
}

/* Card Footer & Button */
.card-footer {
    margin-top: auto;
    padding-top: 0.75rem;
}

.btn-wash {
    width: 100%;
    padding: 1rem;
    border: none;
    border-radius: var(--border-radius-md);
    background: var(--surface-subtle);
    color: var(--text-primary);
    font-family: inherit;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    border: 1px solid var(--surface-border);
    transition: var(--transition);
}

.btn-wash i {
    font-size: 1.2rem;
}

.btn-wash:hover {
    background: var(--surface-hover);
    transform: translateY(-2px);
}

.btn-wash:active {
    transform: translateY(1px);
}

/* --- Status Specific Styles --- */

/* Green (OK) */
.card.status-green .status-dot { background-color: var(--status-green); color: var(--status-green); }
.card.status-green .status-text { color: var(--status-green); }
.card.status-green .days-count { color: var(--status-green); text-shadow: 0 0 20px var(--status-green-glow); }
.card.status-green .progress-bar { background-color: var(--status-green); }
.card.status-green .icon-container { border-color: var(--status-green-glow); }
.card.status-green .icon-container i { color: var(--status-green); }
.card.status-green .btn-wash:hover { background: var(--status-green); border-color: var(--status-green); box-shadow: var(--shadow-btn); }

/* Yellow (Warning) */
.card.status-yellow .status-dot { background-color: var(--status-yellow); color: var(--status-yellow); }
.card.status-yellow .status-text { color: var(--status-yellow); }
.card.status-yellow .days-count { color: var(--status-yellow); text-shadow: 0 0 20px var(--status-yellow-glow); }
.card.status-yellow .progress-bar { background-color: var(--status-yellow); }
.card.status-yellow .icon-container { border-color: var(--status-yellow-glow); }
.card.status-yellow .icon-container i { color: var(--status-yellow); }
.card.status-yellow .btn-wash:hover { background: var(--status-yellow); border-color: var(--status-yellow); color: #000; box-shadow: var(--shadow-btn); }

/* Orange (Recommended Wash) */
.card.status-orange .status-dot { background-color: var(--status-orange); color: var(--status-orange); }
.card.status-orange .status-text { color: var(--status-orange); }
.card.status-orange .days-count { color: var(--status-orange); text-shadow: 0 0 20px var(--status-orange-glow); }
.card.status-orange .progress-bar { background-color: var(--status-orange); }
.card.status-orange .icon-container { border-color: var(--status-orange-glow); }
.card.status-orange .icon-container i { color: var(--status-orange); }
.card.status-orange .btn-wash { background: rgba(249, 115, 22, 0.1); border-color: rgba(249, 115, 22, 0.3); }
.card.status-orange .btn-wash:hover { background: var(--status-orange); border-color: var(--status-orange); color: #fff; box-shadow: var(--shadow-btn); }

/* Red (Mandatory Wash) */
.card.status-red { border-color: rgba(239, 68, 68, 0.4); }
.card.status-red::before {
    content: '';
    position: absolute;
    top: 0; left: 0; width: 100%; height: 100%;
    box-shadow: inset 0 0 30px var(--status-red-glow);
    pointer-events: none;
    border-radius: inherit;
}
.card.status-red .status-dot { background-color: var(--status-red); color: var(--status-red); animation: pulse 2s infinite; }
.card.status-red .status-text { color: var(--status-red); }
.card.status-red .days-count { color: var(--status-red); text-shadow: 0 0 20px var(--status-red-glow); }
.card.status-red .progress-bar { background-color: var(--status-red); }
.card.status-red .icon-container { background: rgba(239, 68, 68, 0.1); border-color: var(--status-red); }
.card.status-red .icon-container i { color: var(--status-red); }
.card.status-red .btn-wash { background: var(--status-red); color: white; border-color: var(--status-red); box-shadow: 0 4px 15px var(--status-red-glow); animation: shake 5s infinite; }
.card.status-red .btn-wash:hover { background: #dc2626; transform: scale(1.02); }


@keyframes pulse {
    0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
    70% { box-shadow: 0 0 0 10px rgba(239, 68, 68, 0); }
    100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
}

@keyframes shake {
    0%, 90% { transform: translateX(0); }
    92% { transform: translateX(-3px); }
    94% { transform: translateX(3px); }
    96% { transform: translateX(-3px); }
    98% { transform: translateX(3px); }
    100% { transform: translateX(0); }
}

/* Tabs & Categories Navigation */
.tabs-container {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 3rem;
    justify-content: center;
    background: var(--surface-section);
    padding: 0.4rem;
    border-radius: 100px;
    border: 1px solid var(--surface-border);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    width: max-content;
    margin-left: auto;
    margin-right: auto;
    box-shadow: var(--shadow-glass);
}

.tab-btn {
    background: transparent;
    border: none;
    padding: 0.6rem 1.4rem;
    color: var(--text-secondary);
    font-family: inherit;
    font-size: 0.95rem;
    font-weight: 600;
    border-radius: 100px;
    cursor: pointer;
    transition: var(--transition);
}

.tab-btn:hover {
    color: var(--text-primary);
    background: var(--surface-hover);
}

.tab-btn.active {
    color: var(--text-primary);
    background: var(--primary-color);
    box-shadow: var(--shadow-btn);
}

/* Card Header Action Buttons */
.header-actions {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.btn-info {
    background: var(--surface-subtle);
    border: 1px solid var(--surface-border);
