    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: var(--transition);
}

.btn-info i {
    font-size: 1.1rem;
    transition: transform 0.2s ease;
}

.btn-info:hover {
    background: rgba(255, 255, 255, 0.15);
    color: var(--text-primary);
    transform: translateY(-1px);
}

.btn-info.active {
    background: var(--primary-color);
    color: white;
    border-color: var(--primary-color);
    box-shadow: 0 0 12px color-mix(in srgb, var(--primary-color) 40%, transparent);
}

.btn-info.active i {
    transform: rotate(180deg);
}

/* Collapsible Instructions Drawer */
.instructions-collapse {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows 0.3s cubic-bezier(0.4, 0, 0.2, 1), margin 0.3s ease, border 0.3s ease;
    overflow: hidden;
    background: var(--surface-inset);
    border-radius: var(--border-radius-md);
    margin: 0 0 1rem 0;
    border: 1px solid transparent;
}

.instructions-collapse.open {
    grid-template-rows: 1fr;
    margin: 0 0 1.5rem 0;
    border: 1px solid rgba(255, 255, 255, 0.06);
}

.instructions-content {
    min-height: 0;
    padding: 0 1.25rem;
    transition: padding 0.3s ease;
}

.instructions-collapse.open .instructions-content {
    padding: 1.25rem;
}

/* Custom collapse styling for group sub-items to prevent cutoff */
.group-subitem .instructions-collapse {
    background: var(--surface-inset);
    margin: 0;
    border: none;
}
.group-subitem .instructions-collapse.open {
    margin: 0 0 0.75rem 0;
    border: 1px solid rgba(255, 255, 255, 0.06);
}
.group-subitem .instructions-content {
    padding: 0 8px;
    font-size: 0.8rem;
}
.group-subitem .instructions-collapse.open .instructions-content {
    padding: 8px;
}


.instruction-step {
    margin-bottom: 0.75rem;
}

.instruction-step:last-child {
    margin-bottom: 0;
}

.instruction-step-title {
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--primary-color);
    margin-bottom: 0.2rem;
}

/* Let the step title color adapt to status color of parent card */
.card.status-yellow .instruction-step-title { color: var(--status-yellow); }
.card.status-orange .instruction-step-title { color: var(--status-orange); }
.card.status-red .instruction-step-title { color: var(--status-red); }

.instruction-step-text {
    font-size: 0.85rem;
    color: var(--text-primary);
    line-height: 1.45;
}

.instruction-step-text {
    font-size: 0.85rem;
    color: var(--text-primary);
    line-height: 1.45;
}

/* Responsive original */
@media (max-width: 768px) {
    .container {
        padding: 1.5rem;
    }
    .header-title h1 {
        font-size: 1.35rem;
    }
    .cards-grid {
