    opacity: 1;
}

input:disabled,
select:disabled,
textarea:disabled {
    cursor: not-allowed;
    opacity: 0.58;
}

input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
textarea:-webkit-autofill,
textarea:-webkit-autofill:hover,
textarea:-webkit-autofill:focus,
select:-webkit-autofill,
select:-webkit-autofill:hover,
select:-webkit-autofill:focus {
    border-color: var(--surface-border) !important;
    -webkit-text-fill-color: var(--text-primary) !important;
    caret-color: var(--text-primary);
    -webkit-box-shadow: 0 0 0 1000px var(--control-autofill-bg) inset !important;
    box-shadow: 0 0 0 1000px var(--control-autofill-bg) inset !important;
    transition: background-color 0s 600000s, color 0s 600000s;
}

input:-webkit-autofill:focus,
textarea:-webkit-autofill:focus,
select:-webkit-autofill:focus {
    border-color: var(--primary-color) !important;
    -webkit-box-shadow:
        0 0 0 1000px var(--surface-inset) inset,
        0 0 0 3px color-mix(in srgb, var(--primary-color) 22%, transparent) !important;
    box-shadow:
        0 0 0 1000px var(--surface-inset) inset,
        0 0 0 3px color-mix(in srgb, var(--primary-color) 22%, transparent) !important;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[role="button"]:focus-visible {
    outline: 3px solid rgba(96, 165, 250, 0.95);
    outline-offset: 3px;
}

/* Controles visuales compartidos */
.icon-btn {
    display: inline-grid;
    width: 40px;
    min-width: 40px;
    height: 40px;
    flex: 0 0 40px;
    place-items: center;
    padding: 0;
    border: 1px solid var(--surface-border);
    border-radius: 11px;
    background: var(--surface-subtle);
    color: var(--text-secondary);
    font: inherit;
    cursor: pointer;
    transition:
        color 0.18s ease,
        border-color 0.18s ease,
        background 0.18s ease,
        transform 0.18s ease,
        opacity 0.18s ease;
}

.icon-btn > i {
    font-size: 1.15rem;
    line-height: 1;
    pointer-events: none;
}

.icon-btn:hover {
    border-color: rgba(96, 165, 250, 0.48);
    background: color-mix(in srgb, var(--primary-color) 12%, transparent);
    color: var(--text-link);
    transform: translateY(-1px);
}

.icon-btn:active {
    transform: translateY(0);
}

.icon-btn-sm {
    width: 34px;
    min-width: 34px;
    height: 34px;
    flex-basis: 34px;
    border-radius: 9px;
}

.icon-btn.is-primary {
    border-color: color-mix(in srgb, var(--primary-color) 24%, transparent);
    background: color-mix(in srgb, var(--primary-color) 7.000000000000001%, transparent);
    color: var(--text-link);
}

.icon-btn.is-success {
    border-color: rgba(16, 185, 129, 0.26);
    background: rgba(16, 185, 129, 0.08);
    color: var(--status-green);
}

.icon-btn.is-success:hover,
.icon-btn.is-success:focus-visible {
    border-color: rgba(16, 185, 129, 0.55);
    background: rgba(16, 185, 129, 0.16);
    color: var(--status-green);
}

.icon-btn.is-danger {
    border-color: rgba(239, 68, 68, 0.24);
    background: rgba(239, 68, 68, 0.07);
    color: var(--status-red);
}

.icon-btn.is-danger:hover,
.icon-btn.is-danger:focus-visible {
    border-color: rgba(239, 68, 68, 0.52);
    background: rgba(239, 68, 68, 0.15);
    color: var(--status-red);
}

.icon-btn:disabled {
    cursor: not-allowed;
    opacity: 0.42;
    transform: none;
}

.lifecycle-checkbox {
    appearance: none;
    display: inline-grid;
    width: 19px;
    min-width: 19px;
    height: 19px;
    margin: 0;
    place-content: center;
    border: 1px solid rgba(148, 163, 184, 0.48);
    border-radius: 6px;
    background: var(--surface-section);
    color: white;
    cursor: pointer;
    transition: 0.18s ease;
}

.lifecycle-checkbox::before {
    width: 12px;
    height: 12px;
    background: currentColor;
    clip-path: polygon(14% 44%, 0 59%, 40% 100%, 100% 18%, 84% 4%, 39% 72%);
    content: "";
    transform: scale(0);
    transition: transform 0.14s ease;
}

.lifecycle-checkbox:hover {
    border-color: var(--primary-color);
    background: color-mix(in srgb, var(--primary-color) 10%, transparent);
}

.lifecycle-checkbox:checked {
    border-color: var(--primary-color);
    background: var(--primary-color);
    box-shadow: 0 0 10px color-mix(in srgb, var(--primary-color) 32%, transparent);
}

.lifecycle-checkbox:checked::before {
    transform: scale(1);
}

.lifecycle-checkbox:disabled {
    cursor: not-allowed;
    opacity: 0.45;
}

.lifecycle-checkbox-label {
    cursor: pointer;
}

.switch {
    position: relative;
    display: inline-flex;
    width: 48px;
    min-width: 48px;
    height: 28px;
    flex: 0 0 48px;
    align-items: center;
    cursor: pointer;
}

.switch input {
    position: absolute;
    z-index: 1;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    opacity: 0;
    cursor: pointer;
}

.switch .slider {
    position: absolute;
    inset: 0;
    border: 1px solid rgba(148, 163, 184, 0.34);
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.18);
    box-shadow: inset 0 1px 3px rgba(2, 6, 23, 0.32);
    pointer-events: none;
    transition: 0.2s ease;
}

.switch .slider::before {
    position: absolute;
    top: 3px;
    left: 3px;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: #cbd5e1;
    box-shadow: 0 2px 6px rgba(2, 6, 23, 0.4);
    content: "";
    transition: transform 0.2s ease, background 0.2s ease;
}

.switch input:checked + .slider {
    border-color: rgba(96, 165, 250, 0.7);
    background: var(--primary-color);
}

.switch input:checked + .slider::before {
    background: #ffffff;
    transform: translateX(20px);
}

.switch input:focus-visible + .slider {
    outline: 3px solid rgba(96, 165, 250, 0.42);
    outline-offset: 3px;
}

.switch input:disabled + .slider {
    cursor: not-allowed;
    opacity: 0.45;
}

@media (pointer: coarse), (max-width: 600px) {
    .icon-btn,
    .icon-btn-sm {
        width: 44px;
        min-width: 44px;
        height: 44px;
        flex-basis: 44px;
    }

    .lifecycle-checkbox-label {
        min-height: 44px;
    }

    .switch {
        height: 44px;
    }

    .switch .slider {
        top: 8px;
        bottom: 8px;
    }
}

