    padding: 0.85rem 1rem;
    border: 1px dashed rgba(148, 163, 184, 0.24);
    border-radius: 12px;
    color: var(--text-secondary);
}

.custom-trackers-empty > i {
    flex: 0 0 auto;
    color: var(--primary-color);
    font-size: 1.55rem;
}

.custom-trackers-empty > div {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: 0.15rem;
    min-width: 0;
}

.custom-trackers-empty strong {
    color: var(--text-primary);
    font-size: 0.88rem;
}

.custom-trackers-empty span {
    font-size: 0.76rem;
}

.custom-tracker-card {
    position: relative;
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 0.8rem;
    padding: 1rem;
    overflow: visible;
    border: 1px solid color-mix(in srgb, var(--custom-status-color) 38%, transparent);
    border-top: 3px solid var(--custom-status-color);
    border-radius: 14px;
    background: linear-gradient(150deg, color-mix(in srgb, var(--surface-solid) 90%, transparent), color-mix(in srgb, var(--bg-color) 96%, transparent));
    box-shadow: 0 10px 24px rgba(2, 6, 23, 0.22);
}

.custom-tracker-card.is-featured {
    grid-column: 1 / -1;
    background:
        radial-gradient(circle at 92% 12%, color-mix(in srgb, var(--custom-status-color) 14%, transparent), transparent 34%),
        linear-gradient(150deg, color-mix(in srgb, var(--surface-solid) 96%, transparent), color-mix(in srgb, var(--bg-color) 98%, transparent));
    box-shadow:
        0 0 0 1px color-mix(in srgb, var(--custom-status-color) 16%, transparent),
        0 16px 34px rgba(2, 6, 23, 0.3);
}

.custom-tracker-featured-label {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    margin-top: 0.28rem;
    color: #fcd34d;
    font-size: 0.64rem;
    font-weight: 750;
    letter-spacing: 0.035em;
    text-transform: uppercase;
}

.custom-runtime-order-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    flex-wrap: wrap;
    width: 100%;
    margin: 0 0 0.85rem;
}

.custom-runtime-order-default {
    display: flex;
    gap: 0.55rem;
    justify-content: flex-end;
}

.custom-runtime-order-enter,
.custom-runtime-bulk-enter {
    width: auto;
    min-height: 38px;
    margin: 0;
    padding: 0.55rem 0.8rem;
    font-size: 0.78rem;
}

.custom-runtime-order-enter:disabled,
.custom-runtime-bulk-enter:disabled {
    display: none;
}

.custom-runtime-overview {
    display: flex;
    min-width: min(100%, 330px);
    align-items: center;
    gap: 0.65rem;
    padding: 0.55rem 0.7rem;
    border: 1px solid rgba(52, 211, 153, 0.18);
    border-radius: 11px;
    background: rgba(16, 185, 129, 0.055);
}

.custom-runtime-overview[data-tone="overdue"] {
    border-color: rgba(248, 113, 113, 0.28);
    background: rgba(239, 68, 68, 0.075);
}

.custom-runtime-overview[data-tone="upcoming"] {
    border-color: rgba(251, 191, 36, 0.25);
    background: rgba(245, 158, 11, 0.065);
}

.custom-runtime-overview[data-tone="empty"] {
    border-color: rgba(148, 163, 184, 0.18);
    background: rgba(148, 163, 184, 0.05);
}

.custom-runtime-overview-icon {
    display: grid;
    width: 34px;
    height: 34px;
    flex: 0 0 34px;
    place-items: center;
    border-radius: 9px;
    color: #6ee7b7;
    background: rgba(16, 185, 129, 0.1);
}

.custom-runtime-overview[data-tone="overdue"] .custom-runtime-overview-icon {
    color: #fca5a5;
    background: rgba(239, 68, 68, 0.1);
}

.custom-runtime-overview[data-tone="upcoming"] .custom-runtime-overview-icon {
    color: #fcd34d;
    background: rgba(245, 158, 11, 0.1);
}

.custom-runtime-overview[data-tone="empty"] .custom-runtime-overview-icon {
    color: #cbd5e1;
    background: rgba(148, 163, 184, 0.1);
}

.custom-runtime-overview-copy {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 0.1rem;
}

.custom-runtime-overview-copy strong {
    color: var(--text-primary);
    font-size: 0.78rem;
}

.custom-runtime-overview-copy small {
    overflow: hidden;
    color: var(--text-secondary);
    font-size: 0.68rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.custom-runtime-order-active,
.custom-runtime-bulk-active {
    display: flex;
    width: 100%;
    align-items: center;
    justify-content: space-between;
    gap: 0.85rem;
    padding: 0.75rem 0.85rem;
    border: 1px solid rgba(96, 165, 250, 0.28);
    border-radius: 12px;
    background: color-mix(in srgb, var(--primary-color) 10%, transparent);
}

.custom-runtime-bulk-active {
    border-color: rgba(52, 211, 153, 0.3);
    background: rgba(16, 185, 129, 0.085);
}

.custom-runtime-order-active > span,
.custom-runtime-bulk-active > span {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    min-width: 0;
}

.custom-runtime-order-active > span > i,
.custom-runtime-bulk-active > span > i {
    flex: 0 0 auto;
    color: var(--text-link);
    font-size: 1.25rem;
}

.custom-runtime-bulk-active > span > i {
    color: #6ee7b7;
}

.custom-runtime-order-active > span > span,
.custom-runtime-bulk-active > span > span {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 0.12rem;
}

.custom-runtime-order-active strong,
.custom-runtime-bulk-active strong {
    color: var(--text-primary);
    font-size: 0.82rem;
}

.custom-runtime-order-active small,
.custom-runtime-bulk-active small {
    color: var(--text-secondary);
    font-size: 0.7rem;
    line-height: 1.35;
}

.custom-runtime-order-active .btn,
.custom-runtime-bulk-active .btn {
    width: auto;
    min-width: 112px;
    min-height: 38px;
    margin: 0;
    padding: 0.5rem 0.7rem;
    font-size: 0.75rem;
}

.main-section.is-custom-reordering {
    border-radius: 18px;
    background: linear-gradient(145deg, color-mix(in srgb, var(--primary-color) 5.5%, transparent), transparent 54%);
    box-shadow: inset 0 0 0 1px rgba(96, 165, 250, 0.14);
}

.main-section.is-custom-bulk {
    border-radius: 18px;
    background: linear-gradient(145deg, rgba(16, 185, 129, 0.055), transparent 54%);
    box-shadow: inset 0 0 0 1px rgba(52, 211, 153, 0.14);
}

.custom-runtime-sortable-list {
    min-height: 80px;
}

.custom-tracker-card.is-reorderable {
    cursor: grab;
    user-select: none;
}

.custom-tracker-card.is-reorderable:active {
    cursor: grabbing;
}

.custom-card-reorder-handle {
    display: grid;
    width: 36px;
    height: 36px;
    flex: 0 0 36px;
    place-items: center;
    padding: 0;
    border: 1px solid rgba(96, 165, 250, 0.28);
    border-radius: 9px;
    background: color-mix(in srgb, var(--primary-color) 12%, transparent);
    color: var(--text-link);
    cursor: grab;
}

.custom-card-reorder-actions {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 0.45rem;
}

.custom-card-feature-toggle {
    display: grid;
    width: 36px;
    height: 36px;
    flex: 0 0 36px;
    place-items: center;
    padding: 0;
    border: 1px solid rgba(251, 191, 36, 0.3);
    border-radius: 9px;
    color: #fcd34d;
    background: rgba(245, 158, 11, 0.08);
    cursor: pointer;
}

.custom-card-feature-toggle.is-active {
    border-color: rgba(251, 191, 36, 0.68);
    color: var(--surface-inset);
    background: #fbbf24;
    box-shadow: 0 0 0 3px rgba(245, 158, 11, 0.12);
}

.custom-card-individual-only {
    display: inline-flex;
    min-height: 32px;
    align-items: center;
    padding: 0.35rem 0.55rem;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 999px;
    color: var(--text-secondary);
    background: rgba(148, 163, 184, 0.06);
    font-size: 0.66rem;
    font-weight: 700;
}

.custom-card-bulk-toggle {
    display: grid;
    width: 38px;
    height: 38px;
    flex: 0 0 38px;
    place-items: center;
    padding: 0;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 10px;
    color: #cbd5e1;
    background: rgba(148, 163, 184, 0.09);
    cursor: pointer;
}

.custom-card-bulk-toggle[aria-pressed="true"] {
    border-color: rgba(52, 211, 153, 0.65);
    color: #ecfdf5;
    background: rgba(16, 185, 129, 0.72);
}

.custom-tracker-card.is-bulk-selectable {
    cursor: pointer;
    user-select: none;
    transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.custom-tracker-card.is-bulk-selected {
    border-color: rgba(52, 211, 153, 0.82);
    background: linear-gradient(150deg, rgba(6, 78, 59, 0.38), color-mix(in srgb, var(--bg-color) 96%, transparent));
    box-shadow: 0 0 0 2px rgba(52, 211, 153, 0.16), 0 14px 30px rgba(2, 6, 23, 0.28);
    transform: translateY(-1px);
}

.is-custom-reordering .custom-tracker-card .custom-tracker-secondary-action,
.is-custom-reordering .custom-tracker-card .custom-tracker-instructions,
.is-custom-reordering .custom-tracker-card .custom-tracker-history,
.is-custom-reordering .custom-tracker-card .custom-tracker-record {
    display: none !important;
}

.is-custom-bulk .custom-tracker-card .custom-tracker-secondary-action,
.is-custom-bulk .custom-tracker-card .custom-tracker-instructions,
.is-custom-bulk .custom-tracker-card .custom-tracker-history,
.is-custom-bulk .custom-tracker-card .custom-tracker-record {
    display: none !important;
}

.custom-sort-ghost {
    opacity: 0.3 !important;
}

.custom-sort-chosen,
.custom-sort-dragging {
    border-color: rgba(96, 165, 250, 0.82) !important;
    background: #16233a !important;
    box-shadow: 0 18px 44px rgba(2, 6, 23, 0.52) !important;
}

.custom-sort-keyboard-moved {
    animation: custom-reorder-pulse 0.24s ease;
}

@keyframes custom-reorder-pulse {
    0%,
    100% {
        box-shadow: none;
    }
    50% {
        box-shadow: inset 0 0 0 2px rgba(96, 165, 250, 0.65);
    }
}

.custom-tracker-card-header,
.custom-tracker-identity,
.custom-tracker-dates,
.custom-tracker-history-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem;
}

.custom-tracker-identity {
    justify-content: flex-start;
    min-width: 0;
}

.custom-tracker-identity > div {
    min-width: 0;
}

.custom-tracker-identity h3 {
    margin: 0;
    overflow: hidden;
    color: var(--text-primary);
    font-size: 1rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.custom-tracker-icon {
    display: grid;
    width: 36px;
    height: 36px;
    flex: 0 0 36px;
    place-items: center;
    border: 1px solid color-mix(in srgb, var(--custom-status-color) 35%, transparent);
    border-radius: 10px;
    background: color-mix(in srgb, var(--custom-status-color) 9%, transparent);
    color: var(--custom-status-color);
    font-size: 1.15rem;
}

.custom-tracker-status {
    color: var(--custom-status-color);
    font-size: 0.7rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.custom-tracker-menu {
    position: relative;
    flex: 0 0 auto;
}

.custom-tracker-menu summary {
    display: grid;
    width: 34px;
    height: 34px;
    place-items: center;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: var(--surface-subtle);
    color: var(--text-secondary);
    cursor: pointer;
    list-style: none;
}

.custom-tracker-menu summary:hover,
.custom-tracker-menu summary:focus-visible {
    border-color: rgba(96, 165, 250, 0.48);
    background: color-mix(in srgb, var(--primary-color) 12%, transparent);
    color: var(--text-link);
}

.custom-tracker-menu summary::-webkit-details-marker {
    display: none;
}

.custom-tracker-menu-popover {
    position: absolute;
    z-index: 20;
    top: calc(100% + 6px);
    right: 0;
    display: flex;
    width: 190px;
    flex-direction: column;
    gap: 2px;
    padding: 0.35rem;
    border: 1px solid var(--surface-border);
    border-radius: 10px;
    background: var(--surface-elevated);
    box-shadow: 0 14px 30px rgba(0, 0, 0, 0.45);
}

.custom-tracker-menu-popover button {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    width: 100%;
    padding: 0.48rem 0.55rem;
    border: none;
    border-radius: 7px;
    background: transparent;
    color: var(--text-primary);
    font: inherit;
    font-size: 0.78rem;
    text-align: left;
    cursor: pointer;
}

.custom-tracker-menu-popover button:hover:not(:disabled),
.custom-tracker-menu-popover button:focus-visible {
    background: color-mix(in srgb, var(--primary-color) 14.000000000000002%, transparent);
}

.custom-tracker-menu-popover button:disabled {
    opacity: 0.35;
    cursor: not-allowed;
}

.custom-tracker-menu-popover button.danger {
    color: var(--status-red);
}

.custom-tracker-menu-popover button.danger:hover,
.custom-tracker-menu-popover button.danger:focus-visible {
    background: rgba(239, 68, 68, 0.14);
}

.custom-tracker-metric {
    display: flex;
    align-items: baseline;
    gap: 0.4rem;
}

.custom-tracker-metric strong {
    color: var(--custom-status-color);
    font-size: 1.9rem;
    font-variant-numeric: tabular-nums;
    line-height: 1;
}

.custom-tracker-metric span {
    color: var(--text-secondary);
    font-size: 0.78rem;
}

.custom-tracker-dates {
    align-items: flex-start;
    color: var(--text-secondary);
    font-size: 0.72rem;
}

.custom-tracker-dates span {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 0.1rem;
}

.custom-tracker-dates span:last-child {
