    overflow: hidden;
    border-radius: 999px;
    background: var(--progress-track);
}

.custom-tracker-progress span {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: var(--custom-status-color);
    transition: width 0.25s ease;
}

.custom-tracker-prediction {
    margin: -0.2rem 0 0;
    color: var(--text-secondary);
