    background: transparent;
    color: var(--primary-color);
    font: inherit;
    font-size: 0.7rem;
    cursor: pointer;
}

.custom-tracker-history ol {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.custom-tracker-history li {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.3rem 0;
