    justify-content: flex-end;
    gap: 0.4rem;
}

.custom-tracker-history li .custom-history-delete-actions button {
    display: inline-flex;
    width: auto;
    height: auto;
    min-height: 30px;
    padding: 0.35rem 0.55rem;
    border: 1px solid rgba(148, 163, 184, 0.18);
    background: var(--surface-subtle);
    color: var(--text-secondary);
}

.custom-tracker-history li .custom-history-delete-actions button.danger {
    border-color: rgba(248, 113, 113, 0.28);
    background: rgba(239, 68, 68, 0.13);
    color: #fecaca;
}

.custom-tracker-record {
    width: 100%;
    margin: auto 0 0;
}

.custom-trackers-archive {
    margin-top: 1rem;
    padding-top: 1rem;
    border-top: 1px solid rgba(148, 163, 184, 0.13);
}

.custom-trackers-archive-header h3 {
    margin: 0 0 0.2rem;
    color: var(--text-primary);
    font-size: 0.95rem;
}

.custom-trackers-archive-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 0.75rem;
}

.custom-archived-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.7rem;
    border: 1px solid rgba(148, 163, 184, 0.12);
    border-radius: 10px;
    background: var(--surface-inset);
}

.custom-archived-row > div {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    min-width: 0;
}

.custom-archived-row span {
    display: flex;
    min-width: 0;
    flex-direction: column;
}

.custom-archived-row strong {
    overflow: hidden;
    color: var(--text-primary);
    font-size: 0.82rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.custom-archived-row small,
.custom-archive-empty {
    color: var(--text-secondary);
    font-size: 0.72rem;
}

.custom-icon-danger {
    display: grid;
    width: 34px;
    height: 34px;
    place-items: center;
    border: 1px solid rgba(248, 113, 113, 0.2);
    border-radius: 8px;
    background: rgba(239, 68, 68, 0.08);
    color: #f87171;
    cursor: pointer;
}

.custom-delete-confirmation {
