    line-height: 1.4;
}

.custom-threshold-help {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.55rem;
    padding: 0.7rem;
    border: 1px solid rgba(96, 165, 250, 0.16);
    border-radius: 12px;
    background: color-mix(in srgb, var(--primary-color) 5.5%, transparent);
}

.custom-threshold-help > span {
    display: flex;
    min-width: 0;
    align-items: flex-start;
    gap: 0.45rem;
}

.custom-threshold-help > span > i {
    flex: 0 0 auto;
    margin-top: 0.05rem;
    color: var(--text-link);
    font-size: 1rem;
}

.custom-threshold-help > span > span {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 0.08rem;
}

.custom-threshold-help strong {
    color: var(--text-primary);
    font-size: 0.72rem;
}

.custom-threshold-help small {
    display: block;
}

.custom-number-with-unit {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.custom-number-with-unit input {
    width: 100%;
}

.custom-number-with-unit span {
    color: var(--text-secondary);
    font-size: 0.78rem;
}

.custom-tracker-alert-block {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    margin-top: 1rem;
    padding: 0.85rem;
    border: 1px solid rgba(96, 165, 250, 0.16);
    border-radius: 12px;
    background: color-mix(in srgb, var(--primary-color) 6%, transparent);
}

.custom-tracker-alert-toggle {
    position: relative;
    display: grid;
    min-width: 0;
    flex: 1;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.65rem;
    cursor: pointer;
}

.custom-tracker-alert-toggle input {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    opacity: 0;
    pointer-events: none;
}

.custom-alert-icon {
    display: grid;
    width: 38px;
    height: 38px;
    flex: 0 0 38px;
    place-items: center;
    border: 1px solid rgba(96, 165, 250, 0.2);
    border-radius: 10px;
    background: color-mix(in srgb, var(--primary-color) 10%, transparent);
    color: var(--primary-color);
    font-size: 1.1rem;
}

.custom-alert-copy {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 0.1rem;
}

.custom-tracker-alert-toggle strong {
    color: var(--text-primary);
    font-size: 0.84rem;
}

.custom-alert-switch {
    position: relative;
    width: 44px;
    height: 24px;
    flex: 0 0 44px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.16);
    transition: 0.2s ease;
}

.custom-alert-switch > span {
    position: absolute;
    top: 3px;
    left: 3px;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: #cbd5e1;
    box-shadow: 0 1px 4px rgba(2, 6, 23, 0.45);
    transition: transform 0.2s ease, background 0.2s ease;
}

.custom-tracker-alert-toggle input:checked ~ .custom-alert-switch {
    border-color: rgba(96, 165, 250, 0.65);
    background: var(--primary-color);
}

.custom-tracker-alert-toggle input:checked ~ .custom-alert-switch > span {
    transform: translateX(20px);
    background: #fff;
}

.custom-tracker-alert-toggle input:focus-visible ~ .custom-alert-switch {
    outline: 3px solid rgba(96, 165, 250, 0.3);
    outline-offset: 2px;
}

.custom-tracker-alert-time-wrap {
    min-width: 135px;
    margin: 0;
}

.custom-tracker-form-error {
    margin-top: 0.8rem;
    padding: 0.65rem 0.75rem;
    border: 1px solid rgba(248, 113, 113, 0.24);
    border-radius: 9px;
    background: rgba(239, 68, 68, 0.08);
    color: #fecaca;
    font-size: 0.78rem;
}

.custom-tracker-dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.65rem;
    margin-top: 1rem;
}

.custom-tracker-dialog-actions .btn {
    width: auto;
    min-width: 120px;
    margin: 0;
}

.custom-tracker-history-dialog-card {
    width: min(720px, 100%);
}

.custom-tracker-history-dialog .custom-dialog-close {
    width: 44px;
    height: 44px;
}

.custom-history-dialog-summary {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.65rem;
    margin-bottom: 1rem;
}

.custom-history-dialog-summary article {
    display: flex;
    min-width: 0;
    min-height: 78px;
    flex-direction: column;
    justify-content: center;
    gap: 0.25rem;
    padding: 0.75rem;
    border: 1px solid rgba(148, 163, 184, 0.14);
    border-radius: 11px;
    background: var(--surface-inset);
}

.custom-history-dialog-summary span,
.custom-history-dialog-heading small,
.custom-history-dialog-date small {
    color: var(--text-secondary);
    font-size: 0.7rem;
}

.custom-history-dialog-summary strong {
    overflow: hidden;
    color: var(--text-primary);
    font-size: 0.86rem;
    line-height: 1.3;
    text-overflow: ellipsis;
}

.custom-history-dialog-summary .custom-history-dialog-status {
    color: var(--custom-status-color);
    text-transform: uppercase;
}

.custom-history-dialog-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.8rem;
    margin-bottom: 0.7rem;
}

.custom-history-dialog-heading h3 {
    margin: 0 0 0.12rem;
    color: var(--text-primary);
    font-size: 1rem;
}

.custom-history-dialog-heading .btn {
    width: auto;
    min-height: 40px;
    margin: 0;
    padding: 0.55rem 0.75rem;
}

.custom-history-dialog-heading .btn:disabled {
    opacity: 0.42;
    cursor: not-allowed;
}

.custom-history-edit-form {
    margin-bottom: 0.75rem;
    padding: 0.75rem;
    border: 1px solid rgba(96, 165, 250, 0.22);
    border-radius: 11px;
    background: color-mix(in srgb, var(--primary-color) 7.000000000000001%, transparent);
}

.custom-history-edit-form > label {
    display: block;
    margin-bottom: 0.45rem;
    color: var(--text-primary);
    font-size: 0.76rem;
    font-weight: 700;
}

.custom-history-edit-form > div {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    gap: 0.5rem;
}

.custom-history-edit-form .date-input,
.custom-history-edit-form .btn {
    width: 100%;
    min-height: 42px;
    margin: 0;
}

.custom-history-edit-error {
    margin: 0.55rem 0 0;
    color: #fecaca;
    font-size: 0.74rem;
}

.custom-history-dialog-list {
    max-height: min(44vh, 430px);
    overflow-y: auto;
    border: 1px solid rgba(148, 163, 184, 0.14);
    border-radius: 12px;
    background: var(--surface-inset);
    scrollbar-gutter: stable;
}

.custom-history-dialog-list:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

.custom-history-dialog-list ol {
    margin: 0;
    padding: 0;
    list-style: none;
}

.custom-history-dialog-list li {
    display: flex;
    min-height: 58px;
    align-items: center;
    justify-content: space-between;
    gap: 0.8rem;
    padding: 0.62rem 0.75rem;
    border-top: 1px solid rgba(148, 163, 184, 0.09);
}

.custom-history-dialog-list li:first-child {
    border-top: none;
}

.custom-history-dialog-list li.is-confirming {
    align-items: flex-start;
    flex-direction: column;
    background: rgba(239, 68, 68, 0.06);
}

.custom-history-dialog-date {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 0.55rem;
}

.custom-history-dialog-date > i {
    color: var(--primary-color);
    font-size: 1rem;
}

.custom-history-dialog-date > span {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 0.1rem;
}

.custom-history-dialog-date strong {
    color: var(--text-primary);
    font-size: 0.78rem;
    font-variant-numeric: tabular-nums;
}

.custom-history-dialog-delete {
    display: grid;
    width: 36px;
    height: 36px;
    flex: 0 0 36px;
    place-items: center;
    border: 1px solid rgba(248, 113, 113, 0.18);
    border-radius: 8px;
    background: rgba(239, 68, 68, 0.06);
    color: #f87171;
    cursor: pointer;
}

.custom-history-dialog-delete:hover,
.custom-history-dialog-delete:focus-visible {
    border-color: rgba(248, 113, 113, 0.42);
    background: rgba(239, 68, 68, 0.14);
    color: #fecaca;
}

.custom-history-dialog-delete-confirmation {
    display: flex;
    width: 100%;
    align-items: center;
    justify-content: flex-end;
    gap: 0.45rem;
}

.custom-history-dialog-delete-confirmation > span {
    margin-right: auto;
    color: #fecaca;
    font-size: 0.75rem;
    font-weight: 700;
}

.custom-history-dialog-delete-confirmation .btn {
    width: auto;
    min-height: 36px;
    margin: 0;
    padding: 0.42rem 0.65rem;
}

.custom-history-dialog-delete-confirmation .btn-danger {
    border-color: rgba(248, 113, 113, 0.34);
    background: rgba(239, 68, 68, 0.14);
    color: #fecaca;
}

.custom-history-dialog-empty {
    display: flex;
    min-height: 190px;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    gap: 0.35rem;
    padding: 1.5rem;
    color: var(--text-secondary);
    text-align: center;
}

.custom-history-dialog-empty i {
    margin-bottom: 0.2rem;
    color: var(--primary-color);
    font-size: 2rem;
}

.custom-history-dialog-empty strong {
    color: var(--text-primary);
    font-size: 0.9rem;
}

.custom-history-dialog-empty span {
    max-width: 360px;
    font-size: 0.74rem;
    line-height: 1.45;
}

.custom-tracker-history-dialog-actions {
    margin-top: 0.85rem;
}

body.modal-open {
    overflow: hidden;
}

.custom-tracker-toast {
    position: fixed;
    z-index: 2100;
    right: 1rem;
    bottom: 1rem;
    max-width: min(360px, calc(100vw - 2rem));
    padding: 0.75rem 0.9rem;
    border: 1px solid rgba(74, 222, 128, 0.28);
    border-radius: 10px;
    background: #10251d;
    color: #bbf7d0;
    box-shadow: 0 14px 36px rgba(0, 0, 0, 0.38);
    font-size: 0.8rem;
}

.app-toast {
    position: fixed;
    z-index: 2200;
    right: 1rem;
    bottom: 1rem;
    max-width: min(380px, calc(100vw - 2rem));
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.78rem 0.95rem;
    border: 1px solid rgba(74, 222, 128, 0.28);
    border-radius: 11px;
    background: #10251d;
    color: #bbf7d0;
    box-shadow: 0 14px 36px rgba(0, 0, 0, 0.38);
    font-size: 0.82rem;
    font-weight: 600;
}

.app-toast i {
    flex: 0 0 auto;
    font-size: 1.15rem;
}

.app-toast > span {
    min-width: 0;
    flex: 1;
}

.app-toast-action {
    flex: 0 0 auto;
    padding: 0.34rem 0.55rem;
    border: 1px solid currentColor;
    border-radius: 7px;
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: pointer;
}

.app-toast-action:hover,
.app-toast-action:focus-visible {
    background: rgba(255, 255, 255, 0.1);
    outline: none;
}

.app-toast[data-tone="warning"] {
    border-color: rgba(245, 158, 11, 0.32);
    background: #2b2010;
    color: #fde68a;
}

.app-toast[data-tone="error"] {
    border-color: rgba(248, 113, 113, 0.32);
    background: #2b1518;
    color: #fecaca;
}

.feedback-dialog-open {
    overflow: hidden;
}

.app-feedback-dialog {
    position: fixed;
    z-index: 5000;
    inset: 0;
    display: grid;
    place-items: center;
    padding: 1rem;
    background: rgba(3, 8, 20, 0.76);
    backdrop-filter: blur(8px);
}

.app-feedback-panel {
    width: min(480px, 100%);
    max-height: calc(100dvh - 2rem);
    box-sizing: border-box;
    overflow: hidden;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) auto;
    gap: 0.85rem 1rem;
    padding: 1.35rem;
    border: 1px solid rgba(96, 165, 250, 0.24);
    border-radius: 20px;
    background:
        linear-gradient(145deg, rgba(30, 50, 79, 0.96), rgba(14, 27, 48, 0.98));
    box-shadow: 0 24px 70px rgba(0, 0, 0, 0.52);
}

.app-feedback-icon {
    width: 2.7rem;
    height: 2.7rem;
    display: grid;
    place-items: center;
    border: 1px solid rgba(96, 165, 250, 0.3);
    border-radius: 13px;
    background: color-mix(in srgb, var(--primary-color) 13%, transparent);
    color: var(--text-link);
}

.app-feedback-icon i {
    font-size: 1.35rem;
}

.app-feedback-copy {
    min-width: 0;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
}

.app-feedback-copy h2 {
    margin: 0;
    color: var(--text-primary);
    font-size: 1.15rem;
    line-height: 1.3;
}

.app-feedback-copy p {
    margin: 0.42rem 0 0;
    color: var(--text-secondary);
    font-size: 0.9rem;
    line-height: 1.55;
    white-space: pre-line;
    overflow-wrap: anywhere;
}

.app-feedback-details {
    display: grid;
    gap: 0.45rem;
    margin: 0.85rem 0 0;
}

.app-feedback-details > div {
    display: grid;
    grid-template-columns: minmax(92px, 0.7fr) minmax(0, 1.3fr);
    gap: 0.75rem;
    align-items: baseline;
    padding: 0.48rem 0.6rem;
    border: 1px solid rgba(148, 163, 184, 0.13);
    border-radius: 9px;
    background: var(--surface-inset);
}

.app-feedback-details dt,
.app-feedback-details dd {
    min-width: 0;
    margin: 0;
    font-size: 0.82rem;
    overflow-wrap: anywhere;
}

.app-feedback-details dt {
    color: var(--text-secondary);
}

.app-feedback-details dd {
    color: var(--text-primary);
    font-weight: 700;
    text-align: right;
}

.app-feedback-actions {
    grid-column: 1 / -1;
    display: flex;
    justify-content: flex-end;
    gap: 0.65rem;
    margin-top: 0.35rem;
}

.app-feedback-actions .btn {
    width: auto;
    min-width: 112px;
    margin: 0;
}

.app-feedback-dialog[data-tone="success"] .app-feedback-icon {
    border-color: rgba(52, 211, 153, 0.32);
    background: rgba(16, 185, 129, 0.13);
    color: #34d399;
}

.app-feedback-dialog[data-tone="warning"] .app-feedback-icon {
    border-color: rgba(251, 191, 36, 0.32);
    background: rgba(245, 158, 11, 0.13);
    color: var(--status-yellow);
}

.app-feedback-dialog[data-tone="danger"] .app-feedback-icon {
    border-color: rgba(248, 113, 113, 0.34);
    background: rgba(239, 68, 68, 0.14);
    color: #f87171;
}

.app-feedback-danger-button {
    border-color: rgba(248, 113, 113, 0.48) !important;
    background: #dc2626 !important;
    color: #fff !important;
}

@media (max-width: 520px) {
    .app-feedback-panel {
        grid-template-columns: 1fr;
        grid-template-rows: auto minmax(0, 1fr) auto;
        padding: 1.1rem;
        border-radius: 17px;
    }

    .app-feedback-icon {
        width: 2.45rem;
        height: 2.45rem;
    }

    .app-feedback-actions {
        grid-column: 1;
        display: grid;
        grid-template-columns: 1fr 1fr;
    }

    .app-feedback-dialog[data-mode="message"] .app-feedback-actions {
        grid-template-columns: 1fr;
    }

    .app-feedback-actions .btn {
        width: 100%;
        min-width: 0;
    }

    .app-feedback-details > div {
        grid-template-columns: 1fr;
        gap: 0.15rem;
    }

    .app-feedback-details dd {
        text-align: left;
    }
