/* ==========================================================================
   ESTILOS DE BARRA DE DESPLAZAMIENTO (SCROLLBAR) CUSTOM
   ========================================================================== */
/* Para navegadores basados en WebKit (Chrome, Safari, Edge, Opera) */
::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

::-webkit-scrollbar-track {
    background: var(--surface-subtle);
    border-radius: 10px;
}

::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.12);
    border-radius: 10px;
    transition: background 0.2s ease;
}

::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.25);
}

/* Para Firefox */
* {
    scrollbar-width: thin;
    scrollbar-color: rgba(255, 255, 255, 0.12) rgba(255, 255, 255, 0.02);
}

/* ==========================================================================
   CHECKBOX PERSONALIZADO (GLASSMORPHIC & GLOWING)
   ========================================================================== */
.custom-checkbox-container {
    position: relative;
    cursor: pointer;
    user-select: none;
}

/* Ocultar el checkbox nativo */
.custom-checkbox-container input {
    position: absolute;
    opacity: 0;
    cursor: pointer;
    height: 0;
    width: 0;
}

/* El recuadro del checkbox */
.custom-checkbox {
    width: 20px;
    height: 20px;
    background: var(--control-bg);
    border: 1px solid var(--surface-border);
    border-radius: 6px;
    display: inline-block;
    position: relative;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    vertical-align: middle;
}

/* Hover */
.custom-checkbox-container:hover .custom-checkbox {
    border-color: var(--primary-color);
    background: var(--surface-hover);
}

/* Cuando está checked */
.custom-checkbox-container input:checked ~ .custom-checkbox {
    background: var(--primary-color);
    border-color: var(--primary-color);
    box-shadow: 0 0 10px color-mix(in srgb, var(--primary-color) 45%, transparent);
}

.custom-checkbox-container input:focus-visible ~ .custom-checkbox {
    outline: 3px solid rgba(96, 165, 250, 0.42);
    outline-offset: 3px;
}

.custom-checkbox-container input:disabled ~ .custom-checkbox {
    cursor: not-allowed;
    opacity: 0.45;
}

/* El checkmark oculto por defecto */
.custom-checkbox:after {
    content: "";
    position: absolute;
    display: none;
}

/* Mostrar el checkmark cuando está marcado */
.custom-checkbox-container input:checked ~ .custom-checkbox:after {
    display: block;
}

