    min-width: 0;
    align-items: center;
    gap: 0.65rem;
}

.vehicle-odometer-label .icon-container {
    width: 38px;
    height: 38px;
    flex: 0 0 38px;
}

.vehicle-odometer-label .icon-container i {
    color: var(--text-link);
    font-size: 1.25rem;
}

.vehicle-odometer-label > span {
