}

.lenses-dashboard.vehicle-maintenance-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: start;
    gap: 1rem;
}

.vehicle-maintenance-card {
    min-width: 0;
    padding: 1.15rem;
}

.vehicle-maintenance-card > .card-header {
    margin-bottom: 1rem;
}

.vehicle-maintenance-card > .card-header .icon-container {
    width: 42px;
    height: 42px;
}

.vehicle-maintenance-card > .card-header .icon-container i {
    font-size: 1.35rem;
}

.vehicle-fluids-card {
    grid-column: 1 / -1;
}

.vehicle-fluid-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
}

.vehicle-fluid-grid .vehicle-info-card {
    min-width: 0;
    padding: 0.9rem;
}

.vehicle-fluid-grid .vehicle-info-card:hover,
.vehicle-docs-list .vehicle-info-card:hover {
    transform: none;
}

.vehicle-tire-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.25rem 0.75rem;
    padding: 0.75rem 0;
    border-bottom: 1px dashed var(--surface-border);
}

.vehicle-tire-row:first-child {
