.vehicle-issues-card {
    min-width: 0;
    padding: 1.1rem;
}

.vehicle-issue-composer-card > .card-header,
.vehicle-issues-card > .card-header {
    margin-bottom: 0.9rem;
}

.vehicle-issues-card > .card-header {
    align-items: center;
    justify-content: space-between;
}

.vehicle-issue-composer > summary {
    width: 100%;
    box-sizing: border-box;
    list-style: none;
}

.vehicle-issue-composer > summary::-webkit-details-marker {
    display: none;
}

.vehicle-issue-composer[open] > summary {
    margin-bottom: 1rem;
}

.vehicle-add-issue-form {
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
}

.vehicle-issue-composer:not([open]) > .vehicle-add-issue-form {
