}

.vehicle-add-issue-form .time-input,
.vehicle-add-issue-form .btn {
    width: 100%;
}

.vehicle-issues-heading {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 0.75rem;
}

.vehicle-issues-heading h3 {
    margin: 0;
}

.vehicle-issues-list {
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
}

.vehicle-issues-empty {
    margin: 0;
    padding: 1rem;
    color: var(--text-secondary);
    text-align: center;
}

.vehicle-issues-list .vehicle-issue-item {
    margin: 0;
    padding: 0.75rem 0.9rem;
}

.vehicle-issues-list .vehicle-issue-content {
    gap: 0.2rem;
    padding-right: 0.85rem;
}

@media (max-width: 1000px) {
    .health-tracker-host {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lenses-dashboard.vehicle-issues-layout {
        grid-template-columns: minmax(0, 1fr);
    }
}

@media (max-width: 760px) {
    .health-controls-grid,
    .health-tracker-host,
    .lenses-dashboard.vehicle-maintenance-grid,
    .vehicle-fluid-grid {
        grid-template-columns: minmax(0, 1fr);
    }

    .health-tracker-host {
        grid-column: auto;
    }

    .vehicle-fluids-card {
        grid-column: auto;
    }

    .vehicle-odometer-row {
        align-items: stretch;
        flex-direction: column;
    }

    .vehicle-odometer-field {
        justify-content: flex-end;
    }

    .vehicle-odometer-field .number-input {
        width: min(100%, 180px);
    }

    .vehicle-tire-row {
        grid-template-columns: minmax(0, 1fr);
    }

    .vehicle-tire-row > .btn-record,
    .vehicle-tire-row > .migration-guide {
        width: 100%;
        grid-column: 1;
        grid-row: auto;
    }

    .vehicle-issue-item {
        align-items: stretch;
        flex-direction: column;
        gap: 0.75rem;
    }

    .vehicle-issues-list .vehicle-issue-content {
        padding-right: 0;
    }

    .vehicle-issue-item .btn-solve {
        min-height: 44px;
        justify-content: center;
    }
}

@media (max-width: 480px) {
    .health-blood-card .health-control-card-body {
        grid-template-columns: minmax(0, 1fr);
    }

    .health-blood-card .health-primary-action,
    .health-blood-card .health-history-disclosure {
        grid-column: 1;
    }

    .health-form-actions {
        grid-template-columns: minmax(0, 1fr);
    }

    .vehicle-docs-list .vehicle-info-card {
        align-items: stretch !important;
    }

    .vehicle-docs-list .vehicle-info-card > div:last-child {
        width: 100%;
    }

    .vehicle-docs-list .date-input {
        min-width: 0;
        width: 100% !important;
    }
}

/* ==========================================================================
   APARIENCIA: TEMA OSCURO / CLARO
   ========================================================================== */
