    font-size: 0.92rem;
    font-weight: 600;
    color: var(--text-primary);
    line-height: 1.3;
}

.alert-card-controls {
    display: flex;
    flex-direction: column;
    gap: 0.6rem;
    padding-top: 0.6rem;
    border-top: 1px solid var(--border-subtle);
}

.push-status {
    margin: 0;
    padding: 0.7rem 0.8rem;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 10px;
    background: var(--surface-inset);
    color: var(--text-secondary);
    font-size: 0.78rem;
    line-height: 1.45;
}

.push-status.active {
    border-color: rgba(16, 185, 129, 0.3);
    background: rgba(16, 185, 129, 0.08);
    color: #6ee7b7;
}

.push-status.checking {
    border-color: color-mix(in srgb, var(--primary-color) 28.000000000000004%, transparent);
    background: color-mix(in srgb, var(--primary-color) 8%, transparent);
    color: var(--text-link);
}

.push-status.error {
    border-color: rgba(239, 68, 68, 0.3);
    background: rgba(239, 68, 68, 0.08);
    color: #fca5a5;
}

/* Pinned Freelance Project Tabs */
.tab-btn.pinned {
    background: linear-gradient(135deg, color-mix(in srgb, var(--primary-color) 15%, transparent) 0%, color-mix(in srgb, var(--primary-color) 20%, transparent) 100%);
    border: 1px solid color-mix(in srgb, var(--primary-color) 40%, transparent);
    color: var(--text-link);
    font-weight: 600;
}

.tab-btn.pinned:hover {
    background: linear-gradient(135deg, color-mix(in srgb, var(--primary-color) 25%, transparent) 0%, color-mix(in srgb, var(--primary-color) 30%, transparent) 100%);
    border-color: var(--primary-color);
    color: #ffffff;
}

.tab-btn.pinned.active {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--primary-hover) 100%);
    border-color: var(--text-link);
    color: #ffffff;
    box-shadow: 0 4px 14px color-mix(in srgb, var(--primary-color) 35%, transparent);
}

/* Project Status Tracking Note Badge */
.project-status-pill {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: rgba(245, 158, 11, 0.12);
    border: 1px solid rgba(245, 158, 11, 0.3);
    color: #fbbf24;
    padding: 4px 10px;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-top: 4px;
}

.project-status-pill:hover {
    background: rgba(245, 158, 11, 0.22);
    border-color: #f59e0b;
    color: var(--status-yellow);
}

.project-status-pill.empty-status {
    background: var(--surface-subtle);
    border: 1px dashed var(--surface-border);
    color: var(--text-secondary);
}

.project-status-pill.empty-status:hover {
    background: var(--surface-hover);
    border-color: var(--primary-color);
    color: var(--text-primary);
}

/* ==========================================================================
   RESUMEN DIARIO
   ========================================================================== */

.today-hero {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 2rem;
    margin-bottom: 1.25rem;
    padding: clamp(1.4rem, 3vw, 2rem);
    border: 1px solid rgba(96, 165, 250, 0.24);
    border-radius: 22px;
    background:
        radial-gradient(circle at 92% 0%, color-mix(in srgb, var(--primary-color) 20%, transparent), transparent 42%),
        color-mix(in srgb, var(--surface-solid) 62%, transparent);
    box-shadow: var(--shadow-glass);
}

.today-eyebrow {
    display: block;
    margin-bottom: 0.45rem;
    color: var(--text-link);
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.13em;
    text-transform: uppercase;
}

.today-hero h2 {
    margin: 0;
    font-size: clamp(1.55rem, 3vw, 2.2rem);
    line-height: 1.15;
}

.today-date {
    margin: 0.65rem 0 0;
    color: #cbd5e1;
    font-weight: 600;
}

.today-intro {
    max-width: 660px;
    margin: 0.45rem 0 0;
    color: var(--text-secondary);
    line-height: 1.55;
}

.today-new-task.btn {
    width: auto;
    flex: 0 0 auto;
    padding-inline: 1.15rem;
}

.today-quick-panel {
    margin-bottom: 1.25rem;
    padding: 1rem;
    border: 1px solid rgba(96, 165, 250, 0.18);
    border-radius: 18px;
    background: var(--surface-section);
}

.today-quick-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 0.8rem;
}

.today-quick-heading h3 {
    margin: 0.15rem 0 0;
    font-size: 1rem;
}

.today-quick-kicker {
    color: var(--text-link);
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
}

.today-quick-configure {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    min-height: 34px;
    padding: 0.4rem 0.62rem;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 9px;
    color: var(--text-secondary);
    background: var(--surface-subtle);
    font: inherit;
    font-size: 0.72rem;
    font-weight: 650;
    cursor: pointer;
}

.today-quick-configure:hover {
    border-color: rgba(96, 165, 250, 0.42);
    color: var(--text-link);
    background: color-mix(in srgb, var(--primary-color) 8%, transparent);
}

.today-quick-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.7rem;
}

.today-quick-card {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    gap: 0.2rem 0.65rem;
    min-width: 0;
    min-height: 82px;
    padding: 0.75rem;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 13px;
    text-align: left;
    color: var(--text-primary);
    background: var(--surface-elevated);
    font: inherit;
    cursor: pointer;
    transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.today-quick-card:hover {
    border-color: rgba(96, 165, 250, 0.4);
    background: color-mix(in srgb, var(--primary-color) 9%, transparent);
    transform: translateY(-1px);
}

.today-quick-card > span {
    display: grid;
    grid-row: 1 / span 2;
    width: 38px;
    height: 38px;
    place-items: center;
    border-radius: 11px;
    color: var(--text-link);
    background: color-mix(in srgb, var(--primary-color) 11%, transparent);
    font-size: 1.05rem;
}

.today-quick-card strong {
    overflow: hidden;
    font-size: 0.8rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.today-quick-card small {
    display: -webkit-box;
    overflow: hidden;
    color: var(--text-secondary);
    font-size: 0.66rem;
    line-height: 1.3;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

.today-quick-empty {
    width: 100%;
    min-height: 56px;
    border: 1px dashed rgba(96, 165, 250, 0.28);
    border-radius: 12px;
    color: var(--text-primary);
    background: color-mix(in srgb, var(--primary-color) 4.5%, transparent);
    font: inherit;
    font-size: 0.78rem;
    cursor: pointer;
}

.today-summary {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.85rem;
    margin-bottom: 1.5rem;
}

.today-summary article {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    min-width: 0;
    padding: 1rem;
    border: 1px solid var(--surface-border);
    border-radius: 16px;
    background: var(--surface-elevated);
}

.today-summary-icon {
    display: grid;
    width: 42px;
    height: 42px;
    place-items: center;
    flex: 0 0 auto;
    border-radius: 12px;
    font-size: 1.15rem;
}

.today-summary-icon.tasks {
    color: #fca5a5;
    background: rgba(239, 68, 68, 0.12);
}

.today-summary-icon.projects {
    color: var(--text-link);
    background: color-mix(in srgb, var(--primary-color) 12%, transparent);
}

.today-summary-icon.followups {
    color: #fcd34d;
    background: rgba(245, 158, 11, 0.12);
}

.today-summary article div {
    display: flex;
    min-width: 0;
    flex-direction: column;
}

.today-summary strong {
    color: var(--text-primary);
    font-size: 1.45rem;
    line-height: 1;
}

.today-summary article div span {
    margin-top: 0.3rem;
    overflow: hidden;
    color: var(--text-secondary);
    font-size: 0.78rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.today-groups {
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
}

.today-group {
    overflow: hidden;
    border: 1px solid var(--surface-border);
    border-radius: 18px;
    background: var(--surface-section);
}

.today-group-heading {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.85rem;
    padding: 1rem 1.1rem;
    border-bottom: 1px solid var(--surface-border);
    background: var(--surface-elevated);
}

.today-group-icon {
    display: grid;
    width: 40px;
    height: 40px;
    place-items: center;
    border: 1px solid color-mix(in srgb, var(--primary-color) 25%, transparent);
    border-radius: 12px;
    color: var(--text-link);
    background: color-mix(in srgb, var(--primary-color) 10%, transparent);
    font-size: 1.1rem;
}

.today-group-heading h3 {
    margin: 0;
    font-size: 1rem;
}

.today-group-heading p {
    margin: 0.2rem 0 0;
    color: var(--text-secondary);
    font-size: 0.78rem;
    line-height: 1.4;
}

.today-group-count {
    display: grid;
    min-width: 32px;
    height: 32px;
    place-items: center;
    border-radius: 10px;
    color: var(--text-primary);
    background: color-mix(in srgb, var(--primary-color) 12%, transparent);
    font-weight: 700;
}

.today-items {
    display: flex;
    flex-direction: column;
}

.today-item {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.9rem;
    padding: 1rem 1.1rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.today-item:last-child {
    border-bottom: 0;
}

.today-item.is-urgent {
    background: linear-gradient(90deg, rgba(239, 68, 68, 0.055), transparent 48%);
}

.today-item.is-very-urgent {
    background: linear-gradient(90deg, rgba(220, 38, 38, 0.12), transparent 54%);
}

.today-item-icon {
    display: grid;
    width: 38px;
    height: 38px;
    place-items: center;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 11px;
    color: #cbd5e1;
    background: rgba(148, 163, 184, 0.08);
    font-size: 1.05rem;
}

.today-item.is-urgent .today-item-icon,
.today-item.is-very-urgent .today-item-icon {
    border-color: rgba(239, 68, 68, 0.3);
    color: #fca5a5;
    background: rgba(239, 68, 68, 0.1);
}

.today-item-copy {
    min-width: 0;
}

.today-item-source {
    color: var(--text-link);
    font-size: 0.68rem;
    font-weight: 750;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.today-item-copy h4 {
    margin: 0.2rem 0 0;
    overflow-wrap: anywhere;
    font-size: 0.95rem;
}

.today-item-copy p {
    margin: 0.25rem 0 0;
    color: var(--text-secondary);
    font-size: 0.78rem;
    line-height: 1.45;
}

.today-item-actions {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.today-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    min-height: 36px;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--surface-border);
    border-radius: 10px;
    color: var(--text-primary);
    background: var(--control-bg);
    font: inherit;
    font-size: 0.75rem;
    font-weight: 650;
    cursor: pointer;
    transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.today-action:hover {
    border-color: rgba(96, 165, 250, 0.45);
    background: color-mix(in srgb, var(--primary-color) 10%, transparent);
    transform: translateY(-1px);
}

.today-action-primary {
    border-color: color-mix(in srgb, var(--primary-color) 42%, transparent);
    color: #ffffff;
    background: color-mix(in srgb, var(--primary-color) 78%, transparent);
}

.today-empty {
    display: grid;
    place-items: center;
    min-height: 260px;
    padding: 2rem;
    border: 1px dashed rgba(16, 185, 129, 0.35);
    border-radius: 18px;
    text-align: center;
    background: rgba(16, 185, 129, 0.045);
}

.today-empty > span {
    display: grid;
    width: 58px;
    height: 58px;
    place-items: center;
    border-radius: 18px;
    color: #34d399;
    background: rgba(16, 185, 129, 0.12);
    font-size: 1.8rem;
}

.today-empty h3 {
    margin: 0.9rem 0 0;
}

.today-empty p {
    max-width: 470px;
    margin: 0.45rem 0 0;
    color: var(--text-secondary);
    line-height: 1.55;
}

@media (max-width: 767px) {
    .today-hero {
        flex-direction: column;
        gap: 1.15rem;
    }

    .today-new-task.btn {
        width: 100%;
    }

    .today-summary {
        grid-template-columns: 1fr;
    }

    .today-quick-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .today-summary article div span {
        white-space: normal;
    }

    .today-item {
        grid-template-columns: auto minmax(0, 1fr);
        align-items: start;
    }

    .today-item-actions {
        grid-column: 1 / -1;
        justify-content: flex-end;
        padding-left: 3.3rem;
    }
}

@media (max-width: 420px) {
    .today-quick-heading {
        align-items: flex-start;
    }

    .today-quick-configure {
        font-size: 0;
    }

    .today-quick-configure i {
        font-size: 1rem;
    }

    .today-quick-grid {
        grid-template-columns: 1fr;
    }

    .today-quick-card {
        min-height: 70px;
    }

    .today-group-heading {
        grid-template-columns: auto minmax(0, 1fr);
    }

    .today-group-count {
        display: none;
    }

    .today-item {
        padding: 0.95rem;
    }

    .today-item-actions {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        padding-left: 0;
    }

    .today-item-actions .today-action:only-child {
        grid-column: 1 / -1;
    }
}

/* Plantillas reutilizables de Proyectos */
.project-template-picker {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 1.35rem;
    padding: 1rem;
    border: 1px solid color-mix(in srgb, var(--primary-color) 26%, transparent);
    border-radius: 14px;
    background: color-mix(in srgb, var(--primary-color) 5.5%, transparent);
}

.project-template-picker-copy {
    min-width: 0;
}

.project-template-picker-copy label {
    display: block;
    margin-bottom: 0.3rem;
    color: var(--text-primary);
    font-size: 0.88rem;
    font-weight: 700;
}

.project-template-picker-copy label span {
    color: var(--text-secondary);
    font-weight: 500;
}

.project-template-picker-copy p {
    max-width: 510px;
    margin: 0;
    color: var(--text-secondary);
    font-size: 0.78rem;
    line-height: 1.45;
}

.project-template-picker-actions {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    flex-shrink: 0;
}

.project-template-picker-actions .text-input {
    width: min(260px, 30vw);
    min-width: 190px;
    margin: 0;
}

.project-template-picker-actions .btn {
    width: auto;
    height: 42px;
    margin: 0;
    white-space: nowrap;
}

.project-templates-modal-content {
    width: min(780px, 94vw);
    max-width: 780px;
    max-height: 90vh;
    overflow-y: auto;
}

.project-templates-modal-header,
.project-template-list-heading,
.project-template-form-heading,
.project-template-list-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.project-templates-modal-header {
    align-items: flex-start;
}

.project-templates-modal-header h3,
.project-template-list-heading h4,
.project-template-form-heading h4 {
    margin: 0;
}

.project-templates-modal-header .modal-desc,
.project-template-list-heading p,
.project-template-form-heading p {
    margin: 0.35rem 0 0;
}

.project-template-create-card {
    margin-top: 1.25rem;
    padding: 1rem;
    border: 1px solid color-mix(in srgb, var(--primary-color) 25%, transparent);
    border-radius: 14px;
    background: color-mix(in srgb, var(--primary-color) 5.5%, transparent);
}

.project-template-form-heading {
    margin-bottom: 1rem;
}

.project-template-form-heading p,
.project-template-list-heading p {
    color: var(--text-secondary);
    font-size: 0.78rem;
}

.project-template-form-heading > i {
    color: var(--text-link);
    font-size: 1.5rem;
}

.project-template-budget-option {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    margin-top: 0.2rem;
    padding: 0.75rem;
    border: 1px solid var(--surface-border);
    border-radius: 11px;
    cursor: pointer;
    background: var(--surface-inset);
}

.project-template-budget-option input {
    position: absolute;
    width: 1px;
    height: 1px;
    opacity: 0;
}

.project-template-budget-check {
    display: grid;
    width: 24px;
    height: 24px;
    flex: 0 0 24px;
    place-items: center;
    border: 1px solid rgba(148, 163, 184, 0.5);
    border-radius: 7px;
    color: transparent;
    background: var(--control-bg);
    transition: 160ms ease;
}

.project-template-budget-option input:checked + .project-template-budget-check {
    border-color: var(--primary-color);
    color: #ffffff;
    background: var(--primary-color);
}

.project-template-budget-option input:focus-visible + .project-template-budget-check {
    outline: 3px solid rgba(96, 165, 250, 0.4);
    outline-offset: 2px;
}

.project-template-budget-option strong,
.project-template-budget-option small {
    display: block;
}

.project-template-budget-option small {
    margin-top: 0.15rem;
    color: var(--text-secondary);
}

.project-template-save-button.btn {
    width: auto;
    margin: 0.9rem 0 0 auto;
}

.project-template-list-heading {
    margin: 1.4rem 0 0.75rem;
}

.project-templates-list {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    min-width: 0;
    gap: 0.65rem;
}

.project-template-list-item {
    min-width: 0;
    padding: 0.85rem 0.95rem;
    border: 1px solid var(--surface-border);
    border-radius: 12px;
    background: var(--surface-inset);
}

.project-template-list-copy {
    min-width: 0;
    flex: 1;
}

.project-template-list-copy strong,
.project-template-list-copy span {
    display: block;
}

.project-template-list-copy strong {
    overflow: hidden;
    color: var(--text-primary);
    text-overflow: ellipsis;
    white-space: nowrap;
}

.project-template-list-copy span {
    margin-top: 0.25rem;
    color: var(--text-secondary);
    font-size: 0.76rem;
    overflow-wrap: anywhere;
}

.project-template-list-actions {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    flex-shrink: 0;
}

.project-template-apply {
    min-height: 36px;
    padding: 0.45rem 0.75rem;
    border: 1px solid color-mix(in srgb, var(--primary-color) 40%, transparent);
    border-radius: 9px;
    color: var(--text-primary);
    background: color-mix(in srgb, var(--primary-color) 12%, transparent);
    cursor: pointer;
    font-weight: 700;
}

.project-template-empty {
    padding: 1.35rem;
    border: 1px dashed var(--surface-border);
    border-radius: 12px;
    color: var(--text-secondary);
    text-align: center;
}

@media (max-width: 760px) {
    .project-template-picker {
        align-items: stretch;
        flex-direction: column;
    }

    .project-template-picker-actions {
        align-items: stretch;
        flex-direction: column;
    }

    .project-template-picker-actions .text-input,
    .project-template-picker-actions .btn {
        width: 100%;
        min-width: 0;
    }

    .project-template-create-card .form-row {
        flex-direction: column;
    }

    .project-template-create-card .input-group.half {
        width: 100%;
    }

    .project-template-list-item {
        align-items: stretch;
        flex-direction: column;
    }

    .project-template-list-actions {
        justify-content: flex-end;
    }
}

/* Movimientos recurrentes de Finanzas */
.finance-recurring-due-panel {
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px solid rgba(245, 158, 11, 0.32);
    border-radius: 16px;
    background: rgba(245, 158, 11, 0.055);
}

.finance-recurring-due-heading,
.finance-recurring-due-item,
.finance-recurring-modal-header,
.finance-recurring-form-heading,
.finance-recurring-list-heading,
.finance-recurring-list-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.finance-recurring-due-heading {
    justify-content: flex-start;
}

.finance-recurring-due-icon {
    display: grid;
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    place-items: center;
    border-radius: 12px;
    color: #fbbf24;
    background: rgba(245, 158, 11, 0.13);
    font-size: 1.3rem;
}

.finance-recurring-due-heading h3,
.finance-recurring-modal-header h3,
.finance-recurring-form-heading h4,
.finance-recurring-list-heading h4 {
