}

.finance-recurring-due-copy {
    min-width: 0;
}

.finance-recurring-due-copy strong,
.finance-recurring-due-copy span {
    display: block;
}

.finance-recurring-due-copy strong {
    overflow: hidden;
    color: var(--text-primary);
    text-overflow: ellipsis;
    white-space: nowrap;
}

.finance-recurring-due-copy span {
    margin-top: 0.2rem;
    color: var(--text-secondary);
    font-size: 0.76rem;
}

.finance-recurring-confirm {
    min-height: 38px;
    padding: 0.5rem 0.8rem;
    border: 1px solid rgba(245, 158, 11, 0.42);
    border-radius: 9px;
    color: #fef3c7;
    background: rgba(245, 158, 11, 0.15);
    cursor: pointer;
    font-weight: 700;
    white-space: nowrap;
}

.finance-recurring-modal-content {
    width: min(820px, 94vw);
    max-width: 820px;
    max-height: 90vh;
    overflow-y: auto;
}

.finance-recurring-modal-header {
    align-items: flex-start;
}

.finance-recurring-safety-note {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    margin-top: 1rem;
    padding: 0.75rem 0.85rem;
    border: 1px solid rgba(16, 185, 129, 0.24);
    border-radius: 11px;
    color: #a7f3d0;
    background: rgba(16, 185, 129, 0.07);
    font-size: 0.82rem;
}

.finance-recurring-registration-note {
    overflow-wrap: anywhere;
    margin: -0.5rem 0 1.1rem;
    padding: 0.7rem 0.8rem;
    border: 1px solid rgba(245, 158, 11, 0.3);
    border-radius: 10px;
    color: #fde68a;
    background: rgba(245, 158, 11, 0.08);
    font-size: 0.8rem;
    line-height: 1.45;
}

.finance-recurring-form-card {
    margin-top: 1rem;
    padding: 1rem;
    border: 1px solid color-mix(in srgb, var(--primary-color) 24%, transparent);
    border-radius: 14px;
    background: color-mix(in srgb, var(--primary-color) 4.5%, transparent);
}

.finance-recurring-form-heading {
    align-items: flex-start;
    margin-bottom: 1rem;
}

.finance-recurring-form-heading .btn {
    width: auto;
    margin: 0;
    padding: 0.45rem 0.7rem;
    font-size: 0.76rem;
}

.finance-recurring-amount-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 0.5rem;
}

.finance-recurring-amount-row .number-input {
    width: 100%;
    margin: 0;
}

.finance-recurring-amount-row select.number-input {
    width: auto;
    min-width: 78px;
}

.finance-recurring-save.btn {
    width: auto;
    margin: 0.9rem 0 0 auto;
}

.finance-recurring-list-heading {
    margin: 1.35rem 0 0.75rem;
}

.finance-recurring-list {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    min-width: 0;
    gap: 0.65rem;
}

.finance-recurring-list-item {
    min-width: 0;
    padding: 0.85rem 0.95rem;
    border: 1px solid var(--surface-border);
    border-radius: 12px;
    background: var(--surface-inset);
}

.finance-recurring-list-item.is-paused {
    opacity: 0.65;
}

.finance-recurring-list-copy {
    min-width: 0;
    flex: 1;
}

.finance-recurring-list-copy strong,
.finance-recurring-list-copy span {
    overflow-wrap: anywhere;
    display: block;
}

.finance-recurring-list-copy strong {
    overflow: hidden;
    color: var(--text-primary);
    text-overflow: ellipsis;
    white-space: nowrap;
}

.finance-recurring-list-copy span {
    margin-top: 0.2rem;
    color: var(--text-secondary);
    font-size: 0.76rem;
}

.finance-recurring-list-actions {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    flex-shrink: 0;
}

.finance-recurring-status {
    display: inline-flex;
    align-items: center;
    min-height: 30px;
    padding: 0.3rem 0.6rem;
    border: 1px solid rgba(16, 185, 129, 0.25);
    border-radius: 999px;
    color: #6ee7b7;
    background: rgba(16, 185, 129, 0.08);
    font-size: 0.7rem;
    font-weight: 700;
}

.finance-recurring-list-item.is-paused .finance-recurring-status {
    border-color: var(--surface-border);
    color: var(--text-secondary);
    background: var(--surface-subtle);
}

@media (max-width: 760px) {
    .finance-header-actions {
        width: 100%;
        flex-wrap: wrap;
    }

    .finance-header-actions #finanzas-month-select {
        flex: 1 1 145px;
    }

    .finance-header-actions #btnOpenFinanzasModal,
    .finance-header-actions #btnOpenFinanzasExpenseModal {
        flex: 1 1 160px;
        justify-content: center;
    }

    .finance-recurring-due-item,
    .finance-recurring-list-item {
        align-items: stretch;
        flex-direction: column;
    }

    .finance-recurring-confirm {
        width: 100%;
    }

    .finance-recurring-form-card .form-row {
        flex-direction: column;
    }

    .finance-recurring-form-card .input-group.half {
        width: 100%;
    }

    .finance-recurring-list-actions {
        justify-content: flex-end;
    }

    #btnManageFinanceRecurring {
        order: 3;
        width: 100% !important;
        justify-content: center;
    }
}

.profile-identity-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    min-width: 0;
    flex: 1 1 15rem;
}

.profile-identity-row .icon-container {
    flex-shrink: 0;
}

.profile-identity-copy {
    min-width: 0;
    flex: 1;
}

#profile-email {
    margin: 0;
    max-width: 100%;
    color: var(--text-primary);
    font-size: clamp(0.9rem, 3.8vw, 1.05rem);
    overflow-wrap: anywhere;
    word-break: break-word;
}

/* Rediseño Responsivo de Encabezado de Proyectos */
.project-card-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 12px;
    position: relative;
}

.project-card-info {
    min-width: 0;
    flex: 1;
}

.countdown-badge-wrapper {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 6px;
    flex-shrink: 0;
    max-width: 50%;
}

@media (max-width: 600px) {
    .project-card-header {
        flex-direction: column;
        align-items: stretch;
        gap: 8px;
    }

    .countdown-badge-wrapper {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: center;
        max-width: 100%;
        width: 100%;
        margin-bottom: 4px;
    }

    .countdown-badge-wrapper .countdown-badge {
        white-space: normal !important;
        text-align: center;
        font-size: 0.92rem !important;
        line-height: 1.3;
    }

    .countdown-badge-wrapper .btn-history-delete {
        align-self: center;
    }
}

/* Filtros por Categoría en Seguimientos / Tarjetas */
.tracker-category-filter-bar {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin: 0;
    padding: 6px;
    background: var(--surface-inset);
    border-radius: 12px;
    border: 1px solid var(--surface-border);
}

.tracker-category-tab {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: 8px;
    border: 1px solid transparent;
    background: transparent;
    color: var(--text-secondary);
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.tracker-category-tab:disabled {
    opacity: 0.52;
    cursor: not-allowed;
}

.tracker-category-tab:hover {
    color: var(--text-primary);
    background: var(--surface-subtle);
}

.tracker-category-tab:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

.tracker-category-tab.active {
    background: var(--primary-color);
    color: white;
    border-color: var(--primary-color);
    box-shadow: 0 2px 8px color-mix(in srgb, var(--primary-color) 30%, transparent);
}

.tracker-category-tab .count-pill {
    background: rgba(255, 255, 255, 0.2);
    color: white;
    padding: 2px 6px;
    border-radius: 10px;
    font-size: 0.75rem;
}

/* Botones / Píldoras de Detalle en Finanzas y Proyectos */
.detail-pill-btn {
    background: color-mix(in srgb, var(--primary-color) 12%, transparent) !important;
    border: 1px solid color-mix(in srgb, var(--primary-color) 30%, transparent) !important;
    color: var(--text-link) !important;
    font-size: 0.72rem !important;
    font-weight: 600 !important;
    padding: 3px 10px !important;
    border-radius: 12px !important;
    cursor: pointer !important;
    transition: all 0.2s ease !important;
    text-decoration: none !important;
    display: inline-flex !important;
    align-items: center !important;
    gap: 4px !important;
}

.detail-pill-btn:hover {
    background: color-mix(in srgb, var(--primary-color) 25%, transparent) !important;
    border-color: color-mix(in srgb, var(--primary-color) 50%, transparent) !important;
    color: var(--text-link) !important;
    transform: translateY(-1px);
    box-shadow: 0 2px 8px color-mix(in srgb, var(--primary-color) 20%, transparent);
}

.push-status.warning {
    border-color: rgba(245, 158, 11, 0.32);
    background: rgba(245, 158, 11, 0.08);
    color: #fcd34d;
}

/* Catálogo configurable de Vehículo */
.vehicle-custom-card-host {
    margin-top: 1rem;
}

.vehicle-config-title-host {
    position: relative;
    min-width: 0;
}

.vehicle-config-title-host > .vehicle-config-edit {
    margin-left: auto;
}

.vehicle-config-title-host.is-root {
    padding-right: 42px;
}

.vehicle-config-title-host.is-root > .vehicle-config-edit {
    position: absolute;
    top: -0.35rem;
    right: 0;
    margin-left: 0;
}

.vehicle-dynamic-card {
    min-width: 0;
}

.vehicle-dynamic-card[data-tone="red"] {
    border-color: rgba(239, 68, 68, 0.62);
}

.vehicle-dynamic-card[data-tone="orange"] {
    border-color: rgba(245, 158, 11, 0.58);
}

.vehicle-dynamic-card[data-tone="green"] {
    border-color: rgba(16, 185, 129, 0.45);
}

.vehicle-dynamic-card .card-header {
    align-items: center;
    gap: 0.7rem;
}

.vehicle-dynamic-card-title {
    min-width: 0;
    flex: 1;
}

.vehicle-dynamic-card-title h3,
.vehicle-dynamic-card-title span {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.vehicle-dynamic-card-title h3 {
    margin: 0;
    color: var(--text-primary);
    font-size: 1rem;
}

.vehicle-dynamic-card-title span {
    margin-top: 0.1rem;
    color: var(--text-secondary);
    font-size: 0.7rem;
}

.vehicle-dynamic-card-header-actions {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 0.5rem;
}

.vehicle-dynamic-card-body {
    display: flex;
    flex-direction: column;
    gap: 0.9rem;
}

.vehicle-dynamic-card-state {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    color: var(--text-secondary);
    font-size: 0.8rem;
}

.vehicle-dynamic-card-state strong {
