        justify-content: space-between;
    }

    .vehicle-dynamic-card .badge {
        margin-left: 0;
    }

    .vehicle-dynamic-document-action {
        grid-template-columns: 1fr;
    }
}

/* ==========================================================================
   NAVEGACIÓN ADAPTATIVA
   ========================================================================== */
.adaptive-nav-header,
.adaptive-nav-more {
    display: none;
}

.adaptive-nav-header {
    width: 100%;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem;
    padding: 0.25rem 0.3rem 0.7rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.12);
    margin-bottom: 0.35rem;
}

.adaptive-nav-brand {
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 0.58rem;
    color: var(--text-primary);
    font-weight: 800;
}

.adaptive-nav-brand > i {
    width: 34px;
    height: 34px;
    flex: 0 0 auto;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: var(--primary-color);
    color: white;
    font-size: 1.15rem;
}

.adaptive-nav-collapse {
    width: 34px;
    height: 34px;
    flex: 0 0 auto;
    display: grid;
    place-items: center;
    border: 1px solid var(--surface-border);
    border-radius: 10px;
    background: var(--surface-subtle);
    color: var(--text-secondary);
    cursor: pointer;
}

.adaptive-nav-collapse:hover,
.adaptive-nav-collapse:focus-visible {
    color: var(--text-link);
    border-color: rgba(96, 165, 250, 0.45);
    background: color-mix(in srgb, var(--primary-color) 12%, transparent);
}

.module-visibility-actions {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    gap: 0.55rem;
}

.module-favorite-toggle {
    width: 38px;
    height: 38px;
    display: grid;
    place-items: center;
    border: 1px solid var(--surface-border);
    border-radius: 10px;
    background: var(--surface-subtle);
    color: var(--text-secondary);
    cursor: pointer;
}

.module-favorite-toggle:hover,
.module-favorite-toggle:focus-visible,
.module-favorite-toggle.active {
    border-color: rgba(245, 158, 11, 0.42);
    background: rgba(245, 158, 11, 0.1);
    color: #fbbf24;
}

.adaptive-navigation-layer {
    position: fixed;
    inset: 0;
    z-index: 9200;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    padding: 1rem;
    background: var(--overlay-bg);
    backdrop-filter: blur(8px);
}

body.adaptive-navigation-open {
    overflow: hidden;
}

.adaptive-navigation-sheet {
    width: min(100%, 560px);
    max-height: min(78vh, 690px);
    overflow-y: auto;
    padding: 1rem;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 22px;
    background: var(--surface-elevated);
    box-shadow: 0 24px 70px rgba(0, 0, 0, 0.52);
}

.adaptive-navigation-sheet > header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    padding: 0.25rem 0.2rem 0.9rem;
}

.adaptive-navigation-sheet > header span {
    color: var(--text-link);
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.1em;
}

.adaptive-navigation-sheet > header h2 {
    margin: 0.22rem 0 0;
    font-size: 1.2rem;
}

.adaptive-navigation-list,
.adaptive-navigation-system-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.65rem;
}

.adaptive-navigation-list button,
.adaptive-navigation-system-actions button {
    min-width: 0;
    min-height: 62px;
    padding: 0.8rem;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 13px;
    background: var(--surface-section);
    color: var(--text-primary);
    display: flex;
    align-items: center;
    gap: 0.7rem;
    font: inherit;
    cursor: pointer;
    text-align: left;
}

.adaptive-navigation-list button:hover,
.adaptive-navigation-list button:focus-visible,
.adaptive-navigation-system-actions button:hover,
.adaptive-navigation-system-actions button:focus-visible {
    border-color: rgba(96, 165, 250, 0.42);
    background: color-mix(in srgb, var(--primary-color) 12%, transparent);
}

.adaptive-navigation-list button > i:first-child,
.adaptive-navigation-system-actions button > i {
    color: var(--text-link);
    font-size: 1.25rem;
}

.adaptive-navigation-list button > i:last-child {
    margin-left: auto;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.adaptive-navigation-system-actions {
    margin-top: 0.8rem;
    padding-top: 0.8rem;
    border-top: 1px solid rgba(148, 163, 184, 0.12);
}

.adaptive-navigation-system-actions button span {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.adaptive-navigation-system-actions button small {
    color: var(--text-secondary);
    font-size: 0.68rem;
}

.adaptive-navigation-empty {
    grid-column: 1 / -1;
    padding: 1rem;
    color: var(--text-secondary);
    text-align: center;
    font-size: 0.8rem;
}

@media (min-width: 1100px) {
    .container {
        max-width: none;
        padding-left: 270px;
