@media (min-width: 768px) and (max-width: 1099px) {
    .container {
        max-width: none;
        padding-left: 98px;
    }

    .main-nav {
        position: fixed;
        inset: 0.8rem auto 0.8rem 0.8rem;
        z-index: 800;
        width: 70px;
        max-width: none;
        margin: 0;
        padding: 0.55rem 0.45rem 4.8rem;
