    font: inherit;
    font-size: 0.86rem;
    font-weight: 750;
    cursor: pointer;
}

.project-plan-tab.active,
.project-plan-tab:hover,
.project-plan-tab:focus-visible {
    background: color-mix(in srgb, var(--primary-color) 14.000000000000002%, transparent);
    color: var(--surface-active);
}

.project-plan-panel {
    margin-top: 0.85rem;
}

.project-plan-reading-surface {
    min-height: 260px;
    max-height: 50vh;
    padding: 1.1rem 1.2rem;
    overflow-y: auto;
    border: 1px solid rgba(148, 163, 184, 0.15);
    border-radius: 14px;
    background: var(--surface-inset);
    color: var(--text-primary);
    font-size: 0.96rem;
    line-height: 1.72;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
}

.project-plan-reading-surface.is-empty {
    color: var(--text-secondary);
    font-style: italic;
}

.project-plan-reading-surface.is-phases {
    font-variant-numeric: tabular-nums;
}

.project-plan-editor {
    display: grid;
    gap: 1rem;
}

.project-plan-editor .input-group {
    margin: 0;
}

.project-plan-editor textarea {
    width: 100%;
    min-height: 120px;
    box-sizing: border-box;
    resize: vertical;
}

.project-plan-editor #proj-phases-textarea {
    min-height: 240px;
}

.project-plan-edit-actions {
    margin-top: 1rem;
}

.project-history-modal-content {
    width: min(680px, 92vw);
    max-width: 680px;
    max-height: 86vh;
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    text-align: left;
}

#proj-add-past-income-form .half {
    min-width: 0;
    flex: 1 1 0;
}

#projects-partial-release-modal .modal-content,
#projects-details-modal .modal-content,
#projects-resolve-arbitration-modal .modal-content {
    overflow-wrap: anywhere;
}

.project-add-past-toggle {
    width: auto;
    min-height: 40px;
    flex: 0 0 auto;
    margin: 0;
    padding: 0.5rem 0.75rem;
    font-size: 0.8rem;
    white-space: nowrap;
}

.project-averages-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.4rem;
    margin-bottom: 0.85rem;
    padding: 0.75rem 0.6rem;
    border: 1px solid var(--surface-border);
    border-radius: 12px;
    background: var(--surface-subtle);
    text-align: center;
    font-size: 0.85rem;
    flex-shrink: 0;
}

.project-average-stat { display: flex; flex-direction: column; gap: 2px; min-width: 0; padding-inline: 4px; }
.project-average-stat:not(:last-child) { border-right: 1px solid var(--surface-border); }
.project-average-stat > span { font-size: 0.75rem; color: var(--text-secondary); }
.project-average-stat > strong { font-size: 0.9rem; line-height: 1.4; color: var(--status-green); font-variant-numeric: tabular-nums; white-space: normal; overflow-wrap: anywhere; }
.project-averages-note { margin: -0.35rem 0 0.85rem; font-size: 0.75rem; line-height: 1.5; color: var(--text-secondary); }

.project-monthly-history-list {
    display: flex;
    min-height: 0;
    flex: 1;
    flex-direction: column;
    gap: 0.55rem;
    margin-bottom: 0.9rem;
    padding-right: 0.25rem;
    overflow-y: auto;
}

.project-history-section-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    margin-top: 0.15rem;
    padding: 0.4rem 0.15rem 0.2rem;
}

.project-history-section-heading.is-closed {
    margin-top: 0.65rem;
    border-top: 1px solid var(--surface-border);
    padding-top: 0.85rem;
}

.project-history-section-heading > div {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 0.12rem;
}

.project-history-section-heading span {
    color: var(--text-primary);
    font-size: 0.84rem;
    font-weight: 800;
}

.project-history-section-heading small {
    color: var(--text-secondary);
    font-size: 0.72rem;
}

.history-month-card {
    box-sizing: border-box;
}

.history-month-card.is-current {
    border-color: rgba(234, 179, 8, 0.36);
    background: linear-gradient(120deg, rgba(234, 179, 8, 0.08), var(--surface-color));
}

.history-month-card > summary {
    list-style: none;
}

.history-month-card > summary::-webkit-details-marker {
    display: none;
}

.history-month-title-group,
.history-month-total {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 0.55rem;
}

.history-month-title-group > strong {
    color: var(--text-primary);
    font-size: 0.92rem;
}

.history-month-title-group .badge {
    padding: 2px 6px;
    font-size: 0.58rem;
}

.history-month-total > strong {
    color: var(--status-green);
    font-size: 0.86rem;
    white-space: nowrap;
}

.history-month-card .toggle-icon {
    transition: transform 0.2s ease;
}

.history-month-card[open] .toggle-icon {
    transform: rotate(180deg);
}

.history-month-card:not([open]) > .history-month-details {
    display: none;
}

.history-month-empty,
.project-history-closed-empty {
    margin: 0;
    padding: 0.85rem;
    color: var(--text-secondary);
    font-size: 0.8rem;
    text-align: center;
}

.project-history-closed-empty {
    border: 1px dashed var(--surface-border);
    border-radius: 10px;
}

.history-payment-kind-badge {
    padding: 0.2rem 0.4rem;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 6px;
    color: var(--text-secondary);
    font-size: 0.62rem;
    white-space: nowrap;
}

.finance-annual-modal-content {
    width: min(900px, 92vw);
    max-width: 900px;
    max-height: 86vh;
    box-sizing: border-box;
    overflow-y: auto;
    text-align: left;
}

.finance-annual-modal-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
}

.finance-annual-modal-header h3 {
    margin: 0.15rem 0 0;
}

.finance-annual-modal-content.is-expense .finance-annual-eyebrow,
.finance-annual-modal-content.is-expense .finance-annual-total {
    color: var(--status-orange);
}

.finance-annual-description {
    margin: 0.55rem 0 1rem;
}

.finance-annual-filters {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 180px));
    gap: 0.75rem;
    margin-bottom: 1rem;
}

.finance-annual-filters .input-group {
    margin: 0;
}

.finance-annual-filters .number-input {
    width: 100%;
    height: 42px;
    margin: 0;
    padding: 0.5rem 0.7rem;
}

.finance-annual-table-shell {
    max-height: 58vh;
    overflow: auto;
    border: 1px solid var(--surface-border);
    border-radius: 12px;
}

.finance-annual-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    color: var(--text-secondary);
    font-size: 0.78rem;
    font-variant-numeric: tabular-nums;
}

.finance-annual-table th,
.finance-annual-table td {
    padding: 0.55rem 0.6rem;
    border-bottom: 1px solid var(--divider-color);
    text-align: right;
    white-space: nowrap;
}

.finance-annual-table th:first-child,
.finance-annual-table td:first-child {
    position: sticky;
    left: 0;
    z-index: 1;
    text-align: left;
}

.finance-annual-table thead th {
    position: sticky;
    top: 0;
    z-index: 3;
    border-bottom: 2px solid var(--surface-border);
    background: #18263a;
    color: var(--text-primary);
    font-weight: 750;
}

.finance-annual-table thead th:first-child {
    z-index: 4;
}

.finance-annual-table tbody td:first-child {
    background: var(--surface-color);
    color: var(--text-primary);
    font-weight: 700;
}

.finance-annual-table tfoot th {
    position: sticky;
    bottom: 0;
    z-index: 2;
    border-top: 2px solid var(--surface-border);
    border-bottom: 0;
    background: #18263a;
    color: var(--text-primary);
    font-weight: 800;
}

.finance-annual-row.is-current td {
    background-color: color-mix(in srgb, var(--primary-color) 8%, transparent);
}

.finance-annual-row.is-current td:first-child {
    background: #1c314b;
}

.finance-annual-row.is-future {
    opacity: 0.42;
}

.finance-annual-row td:first-child span {
    display: inline-block;
    margin-left: 0.4rem;
    padding: 0.12rem 0.3rem;
    border-radius: 5px;
    background: color-mix(in srgb, var(--primary-color) 14.000000000000002%, transparent);
    color: var(--text-link);
    font-size: 0.55rem;
    text-transform: uppercase;
}

.finance-annual-total {
    color: var(--status-green);
    font-weight: 850 !important;
}

.finance-annual-mobile-list {
    display: none;
}

@media (max-width: 1000px) {
    .finance-financial-summary {
        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    }
}

@media (max-width: 760px) {
    .financial-summary-grid {
        grid-template-columns: minmax(0, 1fr) !important;
    }

    .project-actions-compact-row {
        flex-wrap: wrap;
    }

    .project-actions-compact-row > .btn,
    .project-actions-compact-row > .dropdown-menu-container > .btn {
        min-height: 44px !important;
        height: 44px !important;
    }

    .project-actions-compact-row .project-btn-icon {
        width: 44px;
        min-width: 44px;
    }

    .project-plan-view-button {
        flex: 1 1 112px;
    }

    .project-plan-modal-content,
    .project-history-modal-content,
    .finance-annual-modal-content {
        width: calc(100vw - 1.25rem);
        max-height: calc(100vh - 1.25rem);
        padding: 1.1rem;
    }

    .project-plan-modal-header {
        align-items: stretch;
        flex-direction: column;
    }

    .project-plan-header-actions {
        justify-content: space-between;
    }

    .project-plan-reading-surface {
        min-height: 230px;
        max-height: 52vh;
        padding: 0.9rem;
    }

    .project-averages-grid {
        grid-template-columns: minmax(0, 1fr);
        text-align: left;
    }

    .project-averages-grid > div {
        padding: 0.35rem !important;
        border-right: 0 !important;
        border-bottom: 1px solid var(--surface-border);
    }

    .project-averages-grid > div:last-child {
        border-bottom: 0;
    }

    .history-project-item {
        align-items: stretch;
        flex-direction: column;
        gap: 0.55rem;
    }

    .history-project-actions {
        justify-content: space-between;
    }

    .finance-annual-filters {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .finance-annual-table-shell {
        display: none;
    }

    .finance-annual-mobile-list {
        display: flex;
        flex-direction: column;
        gap: 0.55rem;
    }

    .finance-annual-mobile-month {
        border: 1px solid var(--surface-border);
        border-radius: 11px;
        background: var(--surface-section);
        overflow: hidden;
    }

    .finance-annual-mobile-month.is-current {
        border-color: rgba(96, 165, 250, 0.45);
    }

    .finance-annual-mobile-month.is-future {
        opacity: 0.48;
    }

    .finance-annual-mobile-month > summary {
        min-height: 48px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
        padding: 0.65rem 0.75rem;
        list-style: none;
        cursor: pointer;
    }

    .finance-annual-mobile-month > summary::-webkit-details-marker {
        display: none;
    }

    .finance-annual-mobile-month > summary > span {
        display: flex;
        min-width: 0;
        align-items: center;
        gap: 0.45rem;
    }

    .finance-annual-mobile-month > summary small {
        padding: 0.12rem 0.3rem;
        border-radius: 5px;
        background: color-mix(in srgb, var(--primary-color) 12%, transparent);
        color: var(--text-link);
        font-size: 0.58rem;
    }

    .finance-annual-mobile-month > summary b {
        color: var(--status-green);
        font-size: 0.82rem;
        white-space: nowrap;
    }

    .finance-annual-modal-content.is-expense .finance-annual-mobile-month > summary b {
        color: var(--status-orange);
    }

    .finance-annual-mobile-detail {
        display: grid;
        gap: 0.85rem;
        padding: 0.75rem;
        border-top: 1px solid var(--surface-border);
    }

    .finance-annual-mobile-month:not([open]) > .finance-annual-mobile-detail {
        display: none;
    }

    .finance-annual-mobile-categories {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 0.4rem;
    }

    .finance-annual-mobile-categories > div {
        display: flex;
        min-width: 0;
        flex-direction: column;
        gap: 0.15rem;
        padding: 0.5rem;
        border-radius: 8px;
        background: var(--surface-subtle);
    }

    .finance-annual-mobile-categories span,
    .finance-annual-mobile-movement small {
        color: var(--text-secondary);
        font-size: 0.66rem;
    }

    .finance-annual-mobile-categories strong {
        color: var(--text-primary);
        font-size: 0.78rem;
    }

    .finance-annual-mobile-movements h5 {
        margin: 0 0 0.45rem;
        color: var(--text-secondary);
        font-size: 0.68rem;
        letter-spacing: 0.07em;
        text-transform: uppercase;
    }

    .finance-annual-mobile-movement {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.65rem;
        padding: 0.5rem 0;
        border-top: 1px solid rgba(255, 255, 255, 0.05);
    }

    .finance-annual-mobile-movement > span {
        display: flex;
        min-width: 0;
        flex-direction: column;
        gap: 0.1rem;
    }

    .finance-annual-mobile-movement > span strong {
        overflow: hidden;
        color: var(--text-primary);
        font-size: 0.74rem;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .finance-annual-mobile-movement > b {
        flex: 0 0 auto;
        color: var(--text-primary);
        font-size: 0.72rem;
    }

    .finance-annual-mobile-empty {
        margin: 0;
        color: var(--text-secondary);
        font-size: 0.72rem;
    }
}

@media (max-width: 480px) {
    .financial-privacy-toggle > span {
        display: none;
    }

    .financial-privacy-toggle {
        width: 44px;
        min-width: 44px;
        padding: 0;
    }

    .project-plan-tabs,
    .finance-annual-filters,
    .finance-annual-mobile-categories {
        grid-template-columns: minmax(0, 1fr);
    }

    .project-plan-tab {
        min-height: 40px;
    }

    .project-plan-edit-actions {
        display: grid;
        grid-template-columns: minmax(0, 1fr);
    }

    .project-plan-edit-actions .btn {
        width: 100%;
    }

    .finance-header-actions {
        width: 100%;
    }

    .finance-header-actions .btn,
    .finance-header-actions .number-input {
        min-height: 44px;
        flex: 1 1 100%;
        width: 100% !important;
    }

    #finanzasList > .card {
        align-items: stretch !important;
        flex-direction: column;
    }

    #finanzasList > .card > div:last-child {
        justify-content: space-between;
    }
}

