@keyframes highlightTargetPulse {
    0% {
        box-shadow: 0 0 0 0 rgba(99, 102, 241, 0.8);
        border-color: var(--primary-color) !important;
    }
    40% {
        box-shadow: 0 0 0 10px rgba(99, 102, 241, 0.3);
        border-color: var(--primary-color) !important;
    }
    100% {
        box-shadow: 0 0 0 0 rgba(99, 102, 241, 0);
    }
}

.highlight-target-pulse {
    animation: highlightTargetPulse 2.2s cubic-bezier(0.25, 1, 0.5, 1);
}

.header-profile-btn {
    display: none;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.85rem;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.1));
    color: var(--text-primary, #f1f5f9);
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-left: auto;
}

.header-profile-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: var(--primary-color, #6366f1);
    color: var(--text-link);
}

.header-profile-btn i {
    font-size: 1.05rem;
}

@media (max-width: 767px) {
    .header-profile-btn {
        display: inline-flex;
    }
}

/* A moving hit box can alternate hover/unhover under a stationary pointer at
   its lower edge. Keep project cards anchored; retain border/shadow feedback. */
#projectsList > .card:hover {
    transform: none;
}

.cloud-sync-notice {
    padding: 0.8rem 1rem;
    margin: 0 0 1rem;
    border: 1px solid var(--status-orange);
    border-radius: 12px;
    color: var(--text-primary);
    background: var(--surface-color);
    font-size: 0.9rem;
}

/* Optional starter configuration */
.starter-pack-card .card-body {
    display: grid;
    gap: 1rem;
}

.starter-pack-status {
    margin: 0;
    color: var(--text-secondary);
}

.starter-pack-safety-note {
    display: flex;
    gap: .75rem;
    align-items: flex-start;
    padding: .85rem 1rem;
    border: 1px solid color-mix(in srgb, var(--primary-color) 32%, transparent);
    border-radius: .85rem;
    color: var(--text-secondary);
    background: color-mix(in srgb, var(--primary-color) 8%, transparent);
}

.starter-pack-safety-note i {
    flex: 0 0 auto;
    margin-top: .1rem;
    color: var(--primary-color);
    font-size: 1.2rem;
}

.starter-pack-dialog {
    position: fixed;
    inset: 0;
    z-index: 10050;
    display: grid;
    place-items: center;
    padding: 1rem;
    background: rgba(3, 8, 20, .76);
    backdrop-filter: blur(8px);
}

.starter-pack-dialog.hidden {
    display: none;
}

.starter-pack-dialog-card {
    width: min(760px, 100%);
    max-height: min(860px, calc(100dvh - 2rem));
    display: grid;
    grid-template-rows: auto auto minmax(0, 1fr) auto auto;
    overflow: hidden;
    border: 1px solid var(--border-color);
    border-radius: 1.25rem;
    background: var(--surface-solid);
    box-shadow: 0 24px 80px rgba(0, 0, 0, .38);
}

.starter-pack-dialog-header {
    display: flex;
    justify-content: space-between;
    gap: 1rem;
    padding: 1.4rem 1.4rem 1rem;
}

.starter-pack-dialog-header h2,
.starter-pack-dialog-header p {
    margin: 0;
}

.starter-pack-dialog-header p {
    margin-top: .45rem;
    color: var(--text-secondary);
    line-height: 1.45;
}

.starter-pack-eyebrow {
    color: var(--primary-color);
    font-size: .72rem;
    font-weight: 800;
    letter-spacing: .09em;
}

.starter-pack-toolbar,
.starter-pack-dialog-actions {
    display: flex;
    align-items: center;
    gap: .65rem;
    padding: .85rem 1.4rem;
    border-top: 1px solid var(--border-color);
}

.starter-pack-toolbar {
    border-top: 0;
    border-bottom: 1px solid var(--border-color);
}

#starter-pack-selection-count {
    margin-left: auto;
    color: var(--text-secondary);
    font-size: .85rem;
}

.starter-pack-options {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: .75rem;
    overflow-y: auto;
    padding: 1rem 1.4rem;
}

.starter-pack-option {
    display: grid;
    grid-template-columns: auto auto minmax(0, 1fr) auto;
    align-items: center;
    gap: .75rem;
    min-width: 0;
    padding: .9rem;
    border: 1px solid var(--border-color);
    border-radius: .9rem;
    background: var(--surface-subtle);
    cursor: pointer;
}

.starter-pack-option:has(input:checked) {
    border-color: var(--primary-color);
    background: color-mix(in srgb, var(--primary-color) 10%, var(--surface-subtle));
}

.starter-pack-option.is-existing {
    opacity: .68;
    cursor: default;
}

.starter-pack-option-icon {
    display: grid;
    place-items: center;
    width: 2.4rem;
    height: 2.4rem;
    border-radius: .7rem;
    color: var(--primary-color);
    background: color-mix(in srgb, var(--primary-color) 14%, transparent);
    font-size: 1.2rem;
}

.starter-pack-option-copy {
    display: grid;
    gap: .2rem;
    min-width: 0;
}

.starter-pack-option-copy small {
    color: var(--text-secondary);
    line-height: 1.35;
}

.starter-pack-existing-badge {
    padding: .25rem .5rem;
    border-radius: 999px;
    color: var(--text-secondary);
    background: var(--surface-solid);
    font-size: .7rem;
    font-weight: 700;
}

.starter-pack-error {
    margin: 0 1.4rem;
    padding: .75rem 1rem;
    border: 1px solid color-mix(in srgb, var(--status-red) 42%, transparent);
    border-radius: .75rem;
    color: var(--status-red);
    background: color-mix(in srgb, var(--status-red) 8%, transparent);
}

.starter-pack-dialog-actions {
    justify-content: flex-end;
}

@media (max-width: 680px) {
    .starter-pack-dialog {
        padding: .5rem;
    }

    .starter-pack-dialog-card {
        max-height: calc(100dvh - 1rem);
        border-radius: 1rem;
    }

    .starter-pack-options {
        grid-template-columns: 1fr;
        padding-inline: 1rem;
    }

    .starter-pack-dialog-header,
    .starter-pack-toolbar,
    .starter-pack-dialog-actions {
        padding-inline: 1rem;
    }

    .starter-pack-toolbar {
        flex-wrap: wrap;
    }

    #starter-pack-selection-count {
        width: 100%;
        margin-left: 0;
    }
}

/* Component-level modal sizing must win over the generic modal rules above. */
#subscription-modal {
    box-sizing: border-box;
    padding: 1rem;
}

#subscription-modal .subscription-modal-content {
    box-sizing: border-box;
    width: min(640px, 100%);
    max-width: 640px;
    max-height: calc(100dvh - 2rem);
    padding: 1.5rem;
    overflow-y: auto;
    text-align: left;
}

@media (max-width: 560px) {
    #subscription-modal {
        align-items: stretch;
        padding: .5rem;
    }

    #subscription-modal .subscription-modal-content {
        width: 100%;
        max-height: calc(100dvh - 1rem);
        padding: 1rem;
        border-radius: 1rem;
    }
}

/* Compact card controls must not inherit full-width form buttons. */
.vehicle-card-controls { display:flex; align-items:center; justify-content:flex-end; gap:.45rem; flex:0 0 auto; min-width:max-content; max-width:100%; }
.vehicle-card-controls > .vehicle-pause-button,
.vehicle-dynamic-card-header-actions > .vehicle-pause-button { width:auto; flex:0 0 auto; }
.vehicle-config-title-host:not(.is-root) { flex-wrap:wrap; gap:.65rem; }
.vehicle-config-title-host:not(.is-root) > :is(h3,h4) { flex:1 1 8rem; min-width:0; overflow-wrap:anywhere; }
.vehicle-config-title-host:not(.is-root) > .icon-container { flex-shrink:0; }
.vehicle-config-title-host.is-root { padding-right:0; }
.vehicle-tire-row > div.vehicle-card-controls { grid-column:2; grid-row:1; min-width:max-content; }
.vehicle-tire-row > .btn-record { grid-row:2; min-width:0; max-width:100%; white-space:normal; }
.vehicle-dynamic-card-header-actions { flex-wrap:wrap; }
.vehicle-dynamic-card-title h3 { white-space:normal; overflow:visible; overflow-wrap:anywhere; }
#extintor-date-input { min-width:0; max-width:100%; }
@media(max-width:560px) {
 .vehicle-tire-row { grid-template-columns:minmax(0,1fr); }
 .vehicle-tire-row > h4 { grid-column:1; grid-row:1; }
 .vehicle-tire-row > div.vehicle-card-controls { grid-column:1; grid-row:2; justify-content:flex-start; }
 .vehicle-tire-row > div:not(.vehicle-card-controls):not(.migration-guide) { grid-column:1; grid-row:3; }
 .vehicle-tire-row > .btn-record { grid-column:1; grid-row:4; width:100%; }
}

/* Source: privacy-lock.css */
body.privacy-locked { overflow: hidden; }
/* Body-level dialogs, tooltips and notifications must disappear as well. */
body.privacy-locked > :not(#privacy-lock-gate):not(script):not(style) { display: none !important; }
#privacy-lock-gate { z-index: 20000; }
#privacy-lock-gate h2 { margin: 0; font-size: 1.5rem; line-height: 1.2; }
.privacy-lock-help, .privacy-lock-preference p, .privacy-lock-settings > p {
    color: var(--text-secondary); line-height: 1.55; margin-block: 1rem;
}
.privacy-lock-preference { margin-bottom: 1.5rem; }
.privacy-lock-settings {
    width: min(430px, calc(100vw - 2rem)); max-height: calc(100dvh - 2rem);
    overflow-y: auto; margin: auto; padding: 1.5rem; border-radius: 20px;
    border: 1px solid var(--surface-border); background: var(--surface-solid); color: var(--text-primary);
}
.privacy-lock-settings::backdrop { background: rgba(0, 0, 0, 0.65); }
.privacy-lock-settings h2 { margin: 0; }
.privacy-lock-settings-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: .75rem; }
.privacy-lock-settings .btn, #privacy-lock-gate .btn { min-height: 44px; white-space: normal; }
/* Keep the extra quick action out of the title/account row on narrow layouts. */
@media (max-width: 1099px) {
    .container > .app-header { margin-top: 3.75rem; }
}
@media (min-width: 1100px) {
    .app-header .header-title { max-width: calc(100% - 450px); }
}

