/* Source: visual.css */
/* Shared visual foundation. Keep business colours, layouts and controls intact.
   Effects are finite and never hold back navigation or a save action. */


body { background: var(--bg-color); }
.glow-orb { display: none; animation: none; }
.card, .custom-tracker-card, .fw-panel, .fw-metric {
    box-shadow: var(--shadow-glass);
    backdrop-filter: none;
}
.card:hover { transform: none; }
.btn-primary, .day-btn.active, .nav-btn.active { color: var(--text-on-accent); }
.adaptive-nav-brand > i { background: var(--primary-color); }
.card, .planning-card, .fw-panel, .fw-metric { border-radius: 12px; }
.adaptive-nav-brand { font-size: 1rem; }
#main-nav { background: var(--surface-section); box-shadow: none; border-radius: 14px; }
.nav-btn { border-radius: 8px; font-size: .88rem; }
.app-context-title { font-weight: 600; }
.text-input, .input-group input, .input-group select, .input-group textarea { border-radius: 8px; }
.profile-main-content > .profile-tab-content > .card { box-shadow: none; }
.reminders-host { max-width: 1250px; margin: 0 auto; }
.reminder-list { display: grid; gap: 0; margin: 1.5rem 0 2rem; }
.reminder-row { display: flex; align-items: center; justify-content: space-between; gap: 1.5rem; padding: 1.25rem 0; border-bottom: 1px solid var(--surface-border); }
.reminder-row > div { min-width: 0; }
.reminder-row h3 { font-size: 1rem; margin: .35rem 0 .5rem; overflow-wrap: anywhere; }
.reminder-row p { color: var(--text-secondary); font-size: .85rem; line-height: 1.55; margin: .3rem 0; overflow-wrap: anywhere; }
.reminder-row small { color: var(--text-secondary); font-size: .76rem; }
.reminder-row .planning-actions { flex-shrink: 0; }
.reminders-host .planning-actions { display: flex; flex-wrap: wrap; align-items: center; gap: .6rem; }
.reminders-host .btn { width: auto; margin: 0; }
.reminders-host .maintenance-card { background: transparent; border: 0; border-bottom: 1px solid var(--surface-border); border-radius: 0; padding: 1.25rem 0; }
.reminders-host .maintenance-card p { font-size: .85rem; color: var(--text-secondary); margin: .5rem 0; }
.reminders-host .maintenance-card h4 { font-size: 1rem; }
.reminders-host .maintenance-card summary { margin-top: .8rem; font-size: .8rem; color: var(--text-secondary); cursor: pointer; }
#reminder-settings > summary, .reminder-advanced > summary { cursor: pointer; padding: 1rem 0; color: var(--text-secondary); }
.reminder-advanced label { margin: .85rem 0; }
.reminder-advanced p { font-size: .8rem; line-height: 1.5; color: var(--text-secondary); }
#reminder-client-context p { padding-bottom: .75rem; }
#reminders-hub [hidden], #recurring-reminder-modal [hidden] { display: none !important; }
.work-content .work-metrics > .card { border-width: 0 0 1px; border-radius: 0; background: transparent; padding: 1rem 0; }
.work-content .work-metrics strong { font-variant-numeric: tabular-nums; font-weight: 600; }
.work-content .work-columns { gap: 2rem; }
.work-content .work-client-card, .work-content .maintenance-card { box-shadow: none; }
.fw-movement { border-width: 0 0 1px; border-radius: 0; background: transparent; padding: 1rem 0; }
.fw-metric { border-width: 0 0 2px; border-radius: 0; background: transparent; padding: 1rem 0; }
.fw-balance, .fw-metric strong, .fw-movement-end { font-variant-numeric: tabular-nums; }
.charging-card, .custom-tracker-card { box-shadow: none; }
.tabs-container, .planning-tabs, .fw-tabs { border-radius: 8px; }
@media (max-width: 600px) {
    .reminder-row { flex-direction: column; align-items: stretch; gap: .8rem; }
    .reminder-row .planning-actions { justify-content: flex-start; }
    .reminder-row button { min-height: 44px; }
}
.btn, button.icon-btn, .nav-btn, .tab-btn, .theme-choice,
.planning-tabs button, .fw-tabs button {
    transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease;
}
.btn { border-radius: 8px; box-shadow: none; line-height: 1.35; }
.btn-primary:hover, .btn-secondary:hover { transform: none; }
.btn:disabled { cursor: not-allowed; opacity: .55; }
.btn-secondary { background: var(--surface-subtle); }
.btn-primary:active:not(:disabled) { background: var(--primary-hover); }
button:focus-visible, summary:focus-visible, a:focus-visible,
input:focus-visible, select:focus-visible, textarea:focus-visible {
    outline: 3px solid var(--primary-color); outline-offset: 3px;
}
.adaptive-nav-brand { border-bottom-color: var(--surface-border); }
.adaptive-nav-brand > i { color: var(--text-on-accent); }
body[data-workspace="work"] .nav-btn.active {
    background: color-mix(in srgb, var(--workspace-accent) 14%, var(--surface-solid));
    color: var(--workspace-accent); box-shadow: inset 3px 0 var(--workspace-accent);
}
#workspace-switch { border-color: color-mix(in srgb, var(--workspace-accent) 45%, var(--surface-border)); }
.app-context-title { letter-spacing: -.035em; }
.planning-heading h2, .fw-toolbar h2, .work-content h2 { letter-spacing: -.035em; }
.planning-heading > div, .planning-heading .planning-actions { min-width: 0; }
.planning-heading p { line-height: 1.55; margin-top: .35rem; }

/* One family of compact, immediately usable tabs across the application. */
.tabs-container, .planning-tabs, .fw-tabs {
    display: flex; gap: 4px; justify-content: flex-start;
    padding: 5px; border-radius: 14px;
    background: var(--surface-section); border: 1px solid var(--surface-border);
    box-shadow: none; max-width: 100%;
}
.tabs-container .tab-btn, .planning-tabs > .btn, #finance-workspace .fw-tabs button {
    width: auto; flex: 0 0 auto; min-height: 40px; margin: 0;
    padding: 10px 15px; border: 1px solid transparent; border-radius: 10px;
    background: transparent; color: var(--text-secondary); box-shadow: none;
    font-size: .88rem; font-weight: 600; white-space: nowrap;
}
.tabs-container .tab-btn.active, .planning-tabs > .btn-primary,
#finance-workspace .fw-tabs [aria-current="page"] {
    background: var(--surface-elevated); color: var(--text-primary);
    border-color: var(--surface-border); box-shadow: 0 1px 3px rgba(0,0,0,.08);
}
.tabs-container .tab-btn.active::after, .planning-tabs > .btn-primary::after { content: none; }
.tabs-container .tab-btn:hover, .planning-tabs > .btn:hover { transform: none; background: var(--surface-hover); }

/* Trackers: a clear identity, a quiet timeline, one main action. */
.custom-tracker-card {
    position: relative; background: var(--surface-color); border: 1px solid var(--surface-border);
    border-top: 2px solid var(--custom-status-color); border-radius: 12px; padding: 18px;
}
:root[data-theme] .custom-tracker-card { background: var(--surface-color); border-top-color: var(--custom-status-color); }
.custom-tracker-card-header { align-items: flex-start; }
.custom-tracker-identity h3 { font-size: 1.06rem; line-height: 1.4; white-space: normal; overflow: visible; text-overflow: clip; overflow-wrap: anywhere; }
.custom-tracker-icon { border-radius: 12px; background: var(--surface-section); }
.custom-tracker-status { letter-spacing: .04em; font-size: .67rem; }
.custom-tracker-metric { margin-top: 10px; margin-bottom: 4px; }
.custom-tracker-metric > strong { font-size: 2.2rem; font-variant-numeric: tabular-nums; letter-spacing: -.055em; }
.custom-tracker-metric > span { font-size: .85rem; }
.custom-tracker-dates { padding: 12px 0; border-top: 1px solid var(--surface-border); }
.custom-tracker-dates strong { margin-top: 4px; font-variant-numeric: tabular-nums; }
.custom-tracker-progress { height: 5px; margin-top: 4px; margin-bottom: 16px; }
.custom-tracker-progress > span { transition: none; }
.custom-tracker-card .tracker-pause-button {
    width: auto; margin: 0; padding: 7px 11px; font-size: .8rem;
    background: transparent; border-color: transparent; color: var(--text-secondary);
}
.custom-tracker-record { margin-top: auto; min-height: 44px; }
.custom-tracker-card.is-featured { background: var(--surface-color); }
.card.status-red .status-dot, .card.status-red .btn-wash { animation: none; }
.save-confirmation {
    position: static; pointer-events: none; white-space: nowrap;
    display: inline-flex; align-items: center; gap: 5px; padding: 6px 10px;
    color: var(--text-primary); background: var(--surface-elevated); border: 1px solid var(--status-green);
    box-shadow: var(--shadow-glass); border-radius: 99px; font-size: .75rem; font-weight: 600;
}
.save-feedback-slot { display: flex; align-items: center; justify-content: flex-end; min-height: 29px; }
.tracker-utility-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: auto; }
.save-confirmation svg { width: 18px; height: 18px; stroke: var(--status-green); stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
#records-list > .card { position: relative; }

/* Charges: this is elapsed time, never a measured battery level. */
.charging-card { position: relative; border-radius: 12px; border-top: 2px solid var(--surface-border); gap: 18px; }
.charging-grid > .charging-card:only-child { max-width: 600px; width: 100%; justify-self: start; }
.charging-card[data-charge-state="active"] { border-top-color: var(--primary-color); }
.charging-card[data-charge-state="due"] { border-top-color: var(--status-orange); }
.charging-icon { background: var(--surface-section); }
.charging-icon svg { width: 26px; height: 26px; stroke: currentColor; fill: none; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.charging-card[data-charge-state="active"] .charging-icon { color: var(--primary-color); background: var(--surface-active); }
.charging-card[data-charge-state="due"] .charging-icon { color: var(--status-orange); }
.charging-status { font-size: .72rem; border: 1px solid var(--surface-border); border-radius: 99px; }
.charging-time strong { font-size: 2.35rem; font-variant-numeric: tabular-nums; }
.charging-time span { display: block; width: 100%; }
.charging-time-track { display: flex; justify-content: space-between; gap: 12px; font-size: .75rem; color: var(--text-secondary); margin-bottom: 7px; }
.charging-progress { height: 6px; display: block; border: 0; border-radius: 99px; overflow: hidden; background: var(--progress-track); }
.charging-progress::-webkit-progress-bar { background: var(--progress-track); }
.charging-progress::-webkit-progress-value { background: var(--primary-color); border-radius: 99px; }
.charging-due .charging-progress::-webkit-progress-value { background: var(--status-orange); }
.charging-remaining { font-size: .82rem; color: var(--text-secondary); margin-top: 9px; }
.charging-due .charging-remaining { color: var(--status-orange); }
.charging-notice { box-shadow: none; padding: 12px; background: var(--surface-section); }
.charging-notice-caption { font-size: .68rem; text-transform: uppercase; letter-spacing: .06em; }
.charging-notice p, .charging-notice small { margin: 0; }
.charging-card details > summary { cursor: pointer; padding: 8px 0; color: var(--text-secondary); font-size: .8rem; }
.charging-card details .charging-settings { margin: 6px 0; }
.charging-secondary .btn { border-color: transparent; background: transparent; color: var(--text-secondary); }
.charging-primary .btn { min-height: 44px; }
.charging-empty { padding: 36px 24px; border: 1px dashed var(--surface-border); border-radius: 18px; text-align: center; color: var(--text-secondary); }
.charging-empty i { display: block; font-size: 2rem; margin-bottom: 10px; }
.charging-guide { margin-top: 20px; color: var(--text-secondary); font-size: .8rem; line-height: 1.6; }
.charging-guide summary { cursor: pointer; padding: 9px 0; }
.charging-guide p { max-width: 75ch; }

/* Projects stay first; the original form and all its templates remain available. */
.projects-page-heading { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 24px; }
.projects-page-heading h2 { margin: 0; font-size: 1.65rem; letter-spacing: -.04em; }
.projects-page-heading p { color: var(--text-secondary); font-size: .88rem; margin: 6px 0 0; }
.projects-page-heading .btn { width: auto; flex-shrink: 0; }
.projects-create-panel { margin-top: 24px; padding: 0; }
.projects-create-panel > summary { cursor: pointer; display: flex; align-items: center; gap: 10px; padding: 20px; font-weight: 600; list-style: none; }
.projects-create-panel > summary::-webkit-details-marker { display: none; }
.projects-create-panel > summary::after { content: '+'; margin-left: auto; color: var(--text-secondary); font-size: 1.3rem; }
.projects-create-panel[open] > summary::after { content: '−'; }
.projects-create-panel > .card-body { padding: 0 24px 24px; }
.projects-financial-summary { grid-template-columns: repeat(4,minmax(0,1fr)) !important; margin-bottom: 24px !important; }
.projects-financial-summary > .card { border-color: var(--surface-border) !important; border-radius: 14px; box-shadow: none; }
#projectsList > .card { position: relative; border-width: 1px; border-left-width: 3px; border-radius: 18px; }
.project-state-line { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; }
.project-state-chip { display: inline-flex; align-items: center; gap: 6px; padding: 5px 9px; border-radius: 99px; font-size: .72rem; font-weight: 600; background: var(--surface-section); color: var(--text-secondary); }
.project-state-chip.is-current { color: var(--text-primary); border: 1px solid var(--surface-border); }
.project-state-chip.is-done { color: var(--status-green); }
.project-state-line > i { color: var(--text-secondary); font-size: .7rem; }
.project-plan-reading-surface.is-phases { border-left: 2px solid var(--primary-color); padding-left: 20px; }
.planning-magazine-cells { display: grid; grid-template-columns: repeat(10,minmax(0,1fr)); gap: 4px; margin-top: 10px; }
.planning-magazine-cells > span { height: 7px; background: var(--progress-track); border-radius: 2px; }
.planning-magazine-cells > span.is-filled { background: var(--primary-color); }
.planning-magazines label { padding: 12px; border: 1px solid var(--surface-border); border-radius: 12px; font-size: .85rem; }
.planning-magazines progress { height: 5px; margin-top: 8px; }
.motion-preference { display: grid; gap: 8px; margin-top: 20px; max-width: 360px; }
.motion-preference select { width: 100%; padding: 11px 12px; background: var(--control-bg); color: var(--text-primary); border: 1px solid var(--surface-border); border-radius: 10px; font: inherit; }
.motion-preference small { color: var(--text-secondary); line-height: 1.5; }
:root[data-theme="light"] .btn-primary { background: var(--primary-color); box-shadow: none; }
:root[data-theme="light"] .btn-secondary { background: var(--surface-subtle); box-shadow: none; }
:root[data-theme="light"] .tabs-container .tab-btn.active,
:root[data-theme="light"] .planning-tabs > .btn-primary { background: var(--surface-elevated); color: var(--text-primary); border-color: var(--surface-border); box-shadow: none; }

/* Calm shared surfaces in the remaining modules. */
.work-metrics > .card, .planning-metrics.card { border-radius: 16px; box-shadow: none; }
.work-metrics strong { font-variant-numeric: tabular-nums; letter-spacing: -.04em; }
.fw-note, .planning-hint { max-width: 85ch; }
.planning-dialog .planning-actions { position: sticky; bottom: -24px; margin-bottom: -24px; padding: 14px 0 24px; background: var(--surface-solid); border-top: 1px solid var(--surface-border); z-index: 2; }
@media (max-width: 900px) {
    .projects-financial-summary { grid-template-columns: repeat(2,minmax(0,1fr)) !important; }
}
@media (max-width: 600px) {
    .tabs-container, .planning-tabs, .fw-tabs { border-radius: 12px; flex-wrap: wrap; }
    .tabs-container .tab-btn, .planning-tabs > .btn, #finance-workspace .fw-tabs button { min-height: 44px; padding: 9px 12px; white-space: normal; }
    .custom-tracker-card, .charging-card { padding: 20px; }
    .custom-tracker-card .tracker-pause-button, .charging-secondary .btn { min-height: 44px; }
    .projects-page-heading { align-items: flex-start; flex-wrap: wrap; }
    .projects-page-heading .btn { min-height: 44px; }
    .projects-create-panel > .card-body { padding: 0 16px 16px; }
    .projects-financial-summary > .card { padding: 12px !important; }
    .planning-dialog .planning-actions { bottom: -18px; margin-bottom: -18px; padding-bottom: 18px; }
}
/* Disable finite/legacy motion too. Status, focus and success text remain. */
:root[data-motion="reduced"] *, :root[data-motion="reduced"] *::before, :root[data-motion="reduced"] *::after {
    animation: none !important; transition: none !important; scroll-behavior: auto !important;
}
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
}

/* Finish inherited blue/glass treatments without changing status semantics. */
.header-actions .btn, .header-actions .icon-btn, .profile-corner-btn,
.header-profile-btn, #privacy-lock-btn, #global-search-btn, #global-quick-task-btn,
#notification-bell-btn { box-shadow: none; background: var(--surface-subtle); border-color: var(--surface-border); color: var(--text-primary); }
.app-context-title, .app-title { background: none; -webkit-text-fill-color: var(--text-primary); color: var(--text-primary); }
.app-context-icon, .app-header-product { color: var(--text-secondary); background: transparent; box-shadow: none; }
.app-header-brand { background: var(--surface-section); border-color: var(--surface-border); box-shadow: none; color: var(--text-secondary); }
#app-context-icon { color: var(--text-secondary); }
.card:hover, .planning-workspace .card:hover, .reminders-host .maintenance-card,
.reminders-host .maintenance-card:hover { box-shadow: none; }
.nav-btn.active { background: var(--surface-elevated); color: var(--text-primary); box-shadow: inset 3px 0 var(--workspace-accent); }
.nav-btn:not(.active):hover { background: var(--surface-subtle); }
:root[data-theme] #main-nav .nav-btn { color: var(--text-secondary); }
:root[data-theme] #main-nav .nav-btn.active { color: var(--text-primary); background: var(--surface-elevated); }
:root[data-theme] #main-nav .nav-btn:hover { color: var(--text-primary); }
.custom-tracker-record { background: var(--primary-color); color: var(--text-on-accent); }
:root[data-theme="light"] .badge.green { color: var(--status-green); }

/* Approved 25/10 direction. Presentation only: module/data identities stay intact. */
body { font-family: var(--font-family); letter-spacing: -.012em; }
h1,h2,h3 { letter-spacing: -.035em; }
.main-section { opacity: 1; transform: none; animation: none; }
.section-title h2,.planning-heading h2,.fw-toolbar h2,.projects-page-heading h2 { font-size: clamp(1.65rem,2.7vw,2rem); line-height: 1.25; font-weight: 700; }
.section-title p,.planning-heading p,.fw-toolbar p { color: var(--text-secondary); line-height: 1.65; }
.card,.custom-tracker-card,.charging-card,.planning-card,.fw-panel,.subscription-card,.today-section,.recovery-panel { border-color: var(--divider-color); border-radius: 20px; box-shadow: none; }
.card-header,.custom-tracker-header { gap: 14px; }
.card-icon,.custom-tracker-icon,.charging-icon { border-radius: 13px; background: var(--surface-subtle); box-shadow: none; }
.card h3,.custom-tracker-card h3 { font-size: 1.05rem; line-height: 1.5; }
.card.status-green,.card.status-yellow,.card.status-orange,.card.status-red,.custom-tracker-card { border-top-width: 1px; border-top-color: var(--divider-color); }
.custom-tracker-number,.days-count,.fw-metric strong,.work-metrics strong { font-variant-numeric: tabular-nums; letter-spacing: -.04em; font-weight: 650; }
.btn,.btn-primary,.btn-secondary,.btn-record,.btn-wash { border-radius: 12px; box-shadow: none; font-weight: 600; line-height: 1.4; }
.btn-primary,.custom-tracker-record { background: var(--primary-color); color: var(--text-on-accent); border-color: transparent; }
.btn-primary:hover,.custom-tracker-record:hover { background: var(--primary-hover); transform: none; }
.btn-secondary { background: var(--surface-subtle); border-color: transparent; color: var(--text-primary); }
.btn-secondary:hover { background: var(--surface-hover); transform: none; }
.btn:focus-visible,button:focus-visible,summary:focus-visible { outline-color: var(--primary-color); }
.text-input,.input-group input,.input-group select,.input-group textarea,
.planning-dialog input:not([type="checkbox"]),.planning-dialog select,.planning-dialog textarea,
.fw-controls select,.work-content select,.motion-preference select { background: var(--control-bg); color: var(--text-primary); border-radius: 11px; border-color: color-mix(in srgb,var(--text-secondary) 55%,var(--surface-color)); box-shadow: none; }
input::placeholder,textarea::placeholder { color: var(--placeholder-color); opacity: 1; }
.tabs-container,.planning-tabs,.fw-tabs { background: transparent; border: 0; border-bottom: 1px solid var(--divider-color); border-radius: 0; box-shadow: none; gap: 16px; padding: 0; margin-bottom: 24px; }
.tabs-container .tab-btn,.planning-tabs>.btn,.fw-tabs button { background: transparent; color: var(--text-secondary); border: 0; border-bottom: 2px solid transparent; border-radius: 0; box-shadow: none; padding: 12px 0; }
:root[data-theme] .tabs-container .tab-btn.active,:root[data-theme] .planning-tabs>.btn-primary,:root[data-theme] .fw-tabs .active { background: transparent; color: var(--text-primary); border-bottom-color: var(--text-primary); }
#tabs-container { border: 0; gap: 7px; }
#tabs-container .tab-btn { border: 1px solid transparent; border-radius: 99px; padding: 10px 16px; }
:root[data-theme] #tabs-container .tab-btn.active { background: var(--surface-subtle); color: var(--text-primary); border-color: var(--divider-color); }
.workspace-picker { display: inline-flex; align-items: center; flex-shrink: 0; gap: 3px; padding: 4px; border-radius: 99px; background: var(--surface-subtle); border: 1px solid var(--divider-color); }
.workspace-picker>button,#workspace-switch { display: inline-flex; justify-content: center; align-items: center; width: auto; min-width: 88px; min-height: 40px; margin: 0; padding: 9px 16px; border: 0; border-radius: 99px; background: transparent; color: var(--text-secondary); font-size: .83rem; font-family: inherit; font-weight: 600; }
.workspace-picker>button.is-active { color: var(--text-primary); background: var(--bg-color); }
.app-header-brand,.header-actions .btn,.header-actions .icon-btn,.profile-corner-btn,.header-profile-btn,#privacy-lock-btn,#global-search-btn,#notification-bell-btn { background: transparent; box-shadow: none; border-color: var(--divider-color); }
#global-quick-task-btn { background: var(--surface-subtle); border-color: transparent; }
.app-header { border-bottom: 1px solid var(--divider-color); padding-bottom: 20px; }
.app-header-product { color: var(--text-secondary); }
.adaptive-nav-brand { color: var(--text-primary); font-size: 1.15rem; font-weight: 700; letter-spacing: -.04em; }
.adaptive-nav-brand>i { background: var(--primary-color); color: var(--text-on-accent); border-radius: 11px; }
#main-nav { background: var(--surface-color); box-shadow: none; }
:root[data-theme] #main-nav .nav-btn { color: var(--text-secondary); }
:root[data-theme] #main-nav .nav-btn.active { color: var(--text-link); background: var(--surface-active); box-shadow: none; }
#main-nav .nav-btn:hover { background: var(--surface-hover); }
.adaptive-navigation-sheet,.quick-task-panel,.global-search-panel,.planning-dialog,.modal-content,.modal-box,.app-dialog-panel,.notification-panel,.privacy-lock-card { background: var(--surface-solid); border-color: var(--divider-color); border-radius: 22px; box-shadow: none; }
.profile-sidebar { border-color: var(--divider-color); background: var(--surface-color); border-radius: 18px; }
.profile-menu-item { border-radius: 10px; color: var(--text-secondary); }
.profile-menu-item.active { background: var(--surface-active); color: var(--text-link); box-shadow: none; }
.profile-menu-group { letter-spacing: .09em; font-size: .7rem; }
.theme-choice { background: var(--surface-solid); border-color: var(--surface-border); border-radius: 15px; }
.theme-choice.is-active { border-color: var(--primary-color); background: var(--surface-active); }
.work-content,#finance-workspace { max-width: 1320px; }
.work-client-card,.client-directory-card { position: relative; }
.work-metrics>.card { background: var(--surface-subtle); border: 0; border-radius: 18px; }
.work-metrics strong { font-size: 2rem; }
.client-secondary { border: 1px solid var(--divider-color); border-radius: 16px; padding: 18px; margin-top: 28px; }
.client-secondary>summary { cursor: pointer; font-weight: 600; }
.client-projects { margin-top: 28px; }
.fw-panel { border-color: var(--divider-color); border-radius: 18px; }
.fw-metrics { gap: 28px; }
.fw-metric { border: 0; padding: 4px 0 24px; }
.fw-metric strong { font-size: clamp(1.7rem,2.8vw,2.4rem); }
.fw-metric small,.fw-note { line-height: 1.7; }
.fw-heading { margin-top: 28px; }
.fw-movement { padding: 16px 0; border-color: var(--divider-color); }
.fw-movement strong { font-variant-numeric: tabular-nums; }
.fw-income-svg { background: transparent; }
.fw-chart-line { stroke: var(--primary-color); }
.fw-chart-dot { fill: var(--surface-color); stroke: var(--primary-color); }
.planning-actions .btn { width: auto; }
.planning-dialog .planning-actions { background: var(--surface-solid); }
.reminder-row,.maintenance-card { border-color: var(--divider-color); }
.access-gate { background: var(--bg-color); }
.access-gate-card { background: var(--surface-solid); border-color: var(--divider-color); box-shadow: none; border-radius: 24px; }
.access-gate-brand,.access-gate-brand i { color: var(--text-primary); }
.today-hero { background: var(--surface-subtle); border-color: var(--divider-color); box-shadow: none; }
.today-quick-actions,.today-panel { border-color: var(--divider-color); background: transparent; }
.today-quick-action { background: var(--surface-subtle); border-color: transparent; box-shadow: none; }
.today-quick-action-icon { color: var(--text-link); background: var(--surface-active); }
.main-section { max-width: 1440px; margin-inline: auto; }
#tracker-container.cards-grid { grid-template-columns: repeat(auto-fill,minmax(min(100%,280px),1fr)); gap: 20px; }
:root[data-theme] .custom-tracker-card { border-top-color: var(--divider-color); }
:root[data-theme] #app-context-title,:root[data-theme] .section-title { background: none; -webkit-text-fill-color: var(--text-primary); color: var(--text-primary); }
:root[data-theme] .custom-tracker-card .custom-tracker-record { background: var(--surface-subtle); color: var(--text-primary); }
:root[data-theme] .custom-tracker-card.status-red .custom-tracker-record,:root[data-theme] .custom-tracker-card.status-orange .custom-tracker-record { background: var(--primary-color); color: var(--text-on-accent); }
.retainer-card { background: var(--surface-subtle); border: 0; border-radius: 18px; padding: 22px; }
.retainer-card>.planning-heading h4 { font-size: 1.05rem; }
.retainer-card>p>strong { font-size: 1.5rem; letter-spacing: -.04em; }
.retainer-section>p,.client-projects>p { font-size: .85rem; color: var(--text-secondary); line-height: 1.7; }
.retainer-section [data-work-action="retainer-pay"],.work-content>.planning-heading [data-work-action="client"] { background: var(--primary-color); color: var(--text-on-accent); }
@media (min-width:1100px) {
    .container { padding-left: 258px; padding-right: 36px; }
    #main-nav { inset: 0 auto 0 0; width: 226px; padding: 24px 14px 96px; border-radius: 0; border-width: 0 1px 0 0; }
    .adaptive-nav-header { margin-bottom: 20px; padding-bottom: 18px; border-bottom: 0; }
    #main-nav .nav-btn { min-height: 46px; margin-bottom: 3px; border-radius: 11px; padding: 12px; font-size: .88rem; }
    .profile-wrapper { left: 22px; bottom: 20px; }
    body.adaptive-nav-collapsed #main-nav { width: 78px; padding-inline: 10px; }
    body.adaptive-nav-collapsed .container { padding-left: 112px; }
    body.adaptive-nav-collapsed .profile-wrapper { left: 22px; }
    body.profile-view-active .container { padding-left: 32px; }
}
@media (min-width:768px) and (max-width:1099px) {
    #main-nav { inset: 0 auto 0 0; border-radius: 0; border-width: 0 1px 0 0; background: var(--surface-color); padding-top: 20px; }
}
@media (max-width:767px) {
    .container { padding-inline: 20px; }
    .app-header { padding-bottom: 16px; }
    #main-nav { border-radius: 0; background: var(--surface-solid); box-shadow: none; }
    :root[data-theme] #main-nav .nav-btn.active { background: var(--surface-solid); color: var(--text-link); }
    .workspace-picker { padding: 3px; }
    .workspace-picker>button,#workspace-switch { min-width: 75px; min-height: 44px; padding: 9px 12px; font-size: .8rem; }
    .btn,.icon-btn,.tab-btn,.profile-menu-item,.text-input,.input-group input,.input-group select,.planning-dialog input:not([type="checkbox"]),.planning-dialog select,.planning-dialog textarea { min-height: 44px; }
    input:not([type="checkbox"]):not([type="range"]),textarea,select { font-size: 16px; }
    .card,.custom-tracker-card,.charging-card { border-radius: 20px; }
    .planning-heading { align-items: flex-start; }
    .planning-actions { gap: 8px; }
    .planning-actions .btn { max-width: 100%; white-space: normal; }
    .fw-metrics { gap: 20px; }
    .fw-metric:last-child { border-top: 1px solid var(--divider-color); padding-top: 18px; }
    .work-filters { gap: 12px; }
    .work-filters label { flex: 1 1 145px; }
    .work-grid { gap: 14px; }
    .profile-sidebar { border-radius: 15px; }
    .profile-menu-item { min-height: 48px; }
}

/* Client cycles use the same components as the configurable Hygiene cards. */
.maintenance-cycle-grid { display: grid; grid-template-columns: repeat(auto-fill,minmax(min(100%,280px),1fr)); gap: 20px; margin-block: 18px 24px; align-items: stretch; }
.maintenance-cycle-card { margin: 0; }
.maintenance-cycle-card .custom-tracker-identity h3 { margin: 0; white-space: normal; overflow-wrap: anywhere; }
.maintenance-cycle-card .cycle-context,.maintenance-cycle-card .cycle-rule { margin: 0; color: var(--text-secondary); font-size: .8rem; line-height: 1.6; }
.maintenance-cycle-card .tracker-utility-row { margin-top: auto; }
.maintenance-cycle-card .tracker-utility-row .btn { background: transparent; border-color: transparent; color: var(--text-secondary); }
.maintenance-cycle-card .custom-tracker-record { width: 100%; }
.maintenance-other { margin-block: 20px; }
.maintenance-other>summary { cursor: pointer; color: var(--text-secondary); }
.maintenance-cycle-grid>.planning-card { grid-column: 1 / -1; }

/* The same native time rows, add/remove controls and compact dialog rhythm. */
.schedule-editor-dialog .custom-tracker-dialog-card { width: min(560px,100%); max-width: 560px; }
.schedule-editor-dialog form { display: grid; gap: 18px; }
.schedule-editor-dialog form>p,.schedule-editor-dialog .care-stage>p { margin: 0; }
.schedule-editor-dialog .care-stage { padding: 0; border: 0; display: grid; gap: 14px; margin: 0; }
.schedule-editor-dialog .care-stage+[data-stage-index] { padding-top: 18px; margin-top: 18px; border-top: 1px solid var(--divider-color); }
.schedule-times-field { display: grid; gap: 10px; color: var(--text-secondary); }
.schedule-times { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 8px; align-items: start; }
.schedule-times>[data-time-rows] { display: grid; gap: 8px; min-width: 0; }
.schedule-time-row { display: flex; align-items: center; gap: 8px; min-width: 0; }
.schedule-time-row input { flex: 1 1 0; min-width: 0; width: 100%; }
.schedule-time-row .icon-btn { flex: 0 0 44px; min-height: 44px; }
.schedule-times>[data-add-time] { min-height: 48px; white-space: nowrap; }
.schedule-optional { border-top: 1px solid var(--divider-color); padding-top: 16px; }
.schedule-optional>summary { font-weight: 600; cursor: pointer; color: var(--text-secondary); line-height: 1.6; }
.schedule-optional[open]>summary { margin-bottom: 16px; }
.schedule-optional>label,.schedule-optional>.planning-hint { margin-block: 14px; }
.reminder-active-switch { display: flex !important; justify-content: space-between; align-items: center; gap: 16px; padding: 16px; border: 1px solid var(--divider-color); border-radius: 16px; background: var(--surface-subtle); }
.reminder-active-switch>span:first-child { display: grid; gap: 4px; }
.reminder-active-switch small { color: var(--text-secondary); font-size: .8rem; line-height: 1.5; font-weight: 400; }
@media (max-width:767px) {
    .maintenance-cycle-grid { gap: 16px; }
    .schedule-editor-dialog .care-form-grid { display: grid; grid-template-columns: minmax(0,1fr) minmax(0,1fr); gap: 12px; }
    .schedule-editor-dialog .care-form-grid input { min-width: 0; width: 100%; }
}
